import { readFile, readdir, stat } from "node:fs/promises";
import { isAbsolute, join, normalize, relative, resolve, sep } from "node:path";
import type { ExecuteScriptResult, JsonValue } from "../../mcp/src/protocol.js";

/**
 * Confirm strings (enforced by mcp/src/bridge-service.ts before these helpers run):
 * - scene:  confirm must be exactly "EXECUTE_SCENE_SCRIPT"
 * - editor: confirm must be exactly "EXECUTE_EDITOR_SCRIPT"
 */

declare const Editor: {
  Project: { path: string };
  App: { path: string; version: string };
  Message: { request(channel: string, message: string, ...args: unknown[]): Promise<unknown> };
  Selection?: unknown;
  Panel?: unknown;
};

declare const module: { paths: string[] };

const MAX_RESULT_BYTES = 256 * 1024;
const DEFAULT_TIMEOUT_MS = 5_000;

function captureLogs(logs: string[]): (...args: unknown[]) => void {
  return (...args: unknown[]) => {
    logs.push(args.map((arg) => {
      if (typeof arg === "string") return arg;
      try {
        return JSON.stringify(arg);
      } catch {
        return String(arg);
      }
    }).join(" "));
  };
}

function serializeResult(value: unknown): { result?: JsonValue; truncated?: boolean; ok: boolean } {
  let json: string;
  try {
    json = JSON.stringify(value);
  } catch {
    return { ok: false };
  }
  if (json === undefined) return { ok: true, result: null };
  if (Buffer.byteLength(json, "utf8") > MAX_RESULT_BYTES) {
    return {
      ok: true,
      truncated: true,
      result: {
        truncated: true,
        byteLength: Buffer.byteLength(json, "utf8"),
        preview: json.slice(0, 2_048),
      },
    };
  }
  return { ok: true, result: JSON.parse(json) as JsonValue };
}

async function withTimeout<T>(promise: Promise<T>, timeoutMs: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<T>((_, reject) => {
        timer = setTimeout(() => reject(new Error(`Script timed out after ${timeoutMs}ms`)), timeoutMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

function assertUnderProject(projectRoot: string, targetPath: string): string {
  const root = resolve(projectRoot);
  const absolute = resolve(isAbsolute(targetPath) ? targetPath : join(root, targetPath));
  const rel = relative(root, absolute);
  if (rel.startsWith("..") || isAbsolute(rel)) {
    throw new Error(`Path escapes project directory: ${targetPath}`);
  }
  return absolute;
}

type NodeLike = {
  name: string;
  uuid: string;
  children: NodeLike[];
};

function findNodeByUuid(root: NodeLike | null, uuid: string): NodeLike | null {
  if (!root) return null;
  if (root.uuid === uuid) return root;
  for (const child of root.children ?? []) {
    const found = findNodeByUuid(child, uuid);
    if (found) return found;
  }
  return null;
}

function findNodeByName(root: NodeLike | null, name: string): NodeLike | null {
  if (!root) return null;
  if (root.name === name) return root;
  for (const child of root.children ?? []) {
    const found = findNodeByName(child, name);
    if (found) return found;
  }
  return null;
}

/**
 * Eval user code in the scene-script process via Function constructor.
 * Injects limited helpers only (no arbitrary require). Expected confirm: EXECUTE_SCENE_SCRIPT.
 */
export async function runSceneUserScript(code: string, timeoutMs = DEFAULT_TIMEOUT_MS): Promise<ExecuteScriptResult> {
  const logs: string[] = [];
  const log = captureLogs(logs);

  try {
    // Scene process already registers Creator's node_modules on module.paths.
    const cc = require("cc") as {
      director: { getScene(): NodeLike | null };
      js: { getClassName(value: object): string };
    };
    const helpers: Record<string, unknown> = {
      cc,
      log,
      getScene: () => cc.director.getScene(),
      findNodeByUuid: (uuid: string) => findNodeByUuid(cc.director.getScene(), uuid),
      findNodeByName: (name: string) => findNodeByName(cc.director.getScene(), name),
    };

    const runner = new Function(
      "helpers",
      `"use strict";
      const { cc, log, getScene, findNodeByUuid, findNodeByName } = helpers;
      return (async () => { ${code} })();`,
    ) as (helpers: Record<string, unknown>) => Promise<unknown>;

    const raw = await withTimeout(Promise.resolve(runner(helpers)), timeoutMs);
    const serialized = serializeResult(raw);
    return {
      ok: serialized.ok,
      ...(serialized.result !== undefined ? { result: serialized.result } : {}),
      ...(logs.length ? { logs } : {}),
      ...(serialized.truncated ? { truncated: true } : {}),
    };
  } catch (error) {
    log(error instanceof Error ? error.message : String(error));
    return { ok: false, logs };
  }
}

/**
 * Eval user code in the editor extension main process.
 * Exposes Editor plus read-only fs/path limited to the project directory.
 * Expected confirm: EXECUTE_EDITOR_SCRIPT.
 */
export async function runEditorUserScript(code: string, timeoutMs = DEFAULT_TIMEOUT_MS): Promise<ExecuteScriptResult> {
  const logs: string[] = [];
  const log = captureLogs(logs);
  const projectRoot = Editor.Project.path;

  try {
    const helpers: Record<string, unknown> = {
      Editor,
      log,
      path: { join, relative, resolve, normalize, isAbsolute, sep },
      fs: {
        async readFile(targetPath: string, encoding: BufferEncoding = "utf8") {
          const absolute = assertUnderProject(projectRoot, targetPath);
          return readFile(absolute, encoding);
        },
        async readdir(targetPath: string) {
          const absolute = assertUnderProject(projectRoot, targetPath);
          return readdir(absolute);
        },
        async stat(targetPath: string) {
          const absolute = assertUnderProject(projectRoot, targetPath);
          const info = await stat(absolute);
          return {
            size: info.size,
            isFile: info.isFile(),
            isDirectory: info.isDirectory(),
            mtimeMs: info.mtimeMs,
          };
        },
      },
      projectPath: projectRoot,
    };

    const runner = new Function(
      "helpers",
      `"use strict";
      const { Editor, log, path, fs, projectPath } = helpers;
      return (async () => { ${code} })();`,
    ) as (helpers: Record<string, unknown>) => Promise<unknown>;

    const raw = await withTimeout(Promise.resolve(runner(helpers)), timeoutMs);
    const serialized = serializeResult(raw);
    return {
      ok: serialized.ok,
      ...(serialized.result !== undefined ? { result: serialized.result } : {}),
      ...(logs.length ? { logs } : {}),
      ...(serialized.truncated ? { truncated: true } : {}),
    };
  } catch (error) {
    log(error instanceof Error ? error.message : String(error));
    return { ok: false, logs };
  }
}
