import { join } from "node:path";
import type {
  JsonValue,
  SceneNode,
  SceneSnapshot,
  SceneValidateIssue,
  SceneValidateResult,
} from "../../mcp/src/protocol.js";

declare const Editor: {
  App: { path: string };
};
declare const module: { paths: string[] };
declare const require: (id: string) => unknown;

type NodeLike = {
  name: string;
  uuid: string;
  children: NodeLike[];
  components: ComponentLike[];
};

type ComponentLike = {
  constructor: object;
  [key: string]: unknown;
};

type CcApi = {
  director: { getScene(): NodeLike | null };
  js: {
    getClassName(instanceOrClass: object): string;
    getClassByName(name: string | object): unknown;
  };
};

const NULL_REF_FIELDS: Record<string, string[]> = {
  Sprite: ["spriteFrame"],
  "cc.Sprite": ["spriteFrame"],
  Label: ["font"],
  "cc.Label": ["font"],
  RichText: ["font", "imageAtlas"],
  "cc.RichText": ["font", "imageAtlas"],
  Mask: ["spriteFrame"],
  "cc.Mask": ["spriteFrame"],
  MeshRenderer: ["mesh"],
  "cc.MeshRenderer": ["mesh"],
  SkinnedMeshRenderer: ["mesh", "skeleton"],
  "cc.SkinnedMeshRenderer": ["mesh", "skeleton"],
  sp: ["skeletonData"],
  "sp.Skeleton": ["skeletonData"],
};

/** Helpers used when validating a serialized scene tree from main / p2. */
export type ValidateSceneHelpers = {
  isComponentRegistered: (className: string) => boolean;
  consoleErrors?: string[];
  reopenable?: boolean;
};

function ensureCcModulePath(): void {
  try {
    module.paths.push(join(Editor.App.path, "node_modules"));
  } catch {
    // main-process callers never need cc
  }
}

function ccApi(): CcApi {
  ensureCcModulePath();
  return require("cc") as CcApi;
}

function componentType(component: ComponentLike): string {
  return ccApi().js.getClassName(component) || component.constructor.constructor.name;
}

function serializeProperty(value: unknown): JsonValue | undefined {
  if (value === null || ["string", "number", "boolean"].includes(typeof value)) return value as JsonValue;
  if (typeof value !== "object") return undefined;
  const record = value as Record<string, unknown>;
  const uuid = typeof record.uuid === "string" ? record.uuid : typeof record._uuid === "string" ? record._uuid : undefined;
  if (uuid) return { uuid, type: value.constructor?.name ?? "Object" };
  return undefined;
}

function componentProperties(component: ComponentLike): Record<string, JsonValue> {
  const properties: Record<string, JsonValue> = {};
  for (const key of ["enabled", "string", "fontSize", "lineHeight", "semanticKey", "action", "spriteFrame", "font", "mesh", "skeleton", "skeletonData", "imageAtlas", "customMaterial"] as const) {
    const serialized = serializeProperty(component[key]);
    if (serialized !== undefined) properties[key] = serialized;
  }
  return properties;
}

function semanticKey(node: NodeLike): string | undefined {
  const identity = node.components.find((component) => componentType(component) === "CreatorAiIdentity");
  return typeof identity?.semanticKey === "string" && identity.semanticKey ? identity.semanticKey : undefined;
}

function nodeKey(node: NodeLike): string {
  return semanticKey(node) ?? node.name;
}

function serializeNode(node: NodeLike): SceneNode {
  const identityKey = semanticKey(node);
  return {
    key: nodeKey(node),
    ...(identityKey ? { semanticKey: identityKey } : {}),
    name: node.name,
    components: node.components.map((component) => ({
      type: componentType(component),
      properties: componentProperties(component),
    })),
    children: node.children.map(serializeNode),
  };
}

function hash(value: string): string {
  let result = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    result ^= value.charCodeAt(index);
    result = Math.imul(result, 16777619);
  }
  return `rev-${(result >>> 0).toString(16).padStart(8, "0")}`;
}

function snapshotFromDirector(): SceneSnapshot {
  const scene = ccApi().director.getScene();
  if (!scene) throw new Error("No scene is currently open");
  const roots = scene.children
    .filter((node) => node.name !== "Editor Scene Foreground" && node.name !== "Editor Scene Background")
    .map(serializeNode);
  return { sceneUrl: scene.name, revision: hash(JSON.stringify(roots)), roots };
}

function isNullishRef(value: unknown): boolean {
  if (value === null || value === undefined) return true;
  if (typeof value === "object" && value !== null) {
    const record = value as Record<string, unknown>;
    if ("uuid" in record) return typeof record.uuid !== "string" || !record.uuid;
  }
  return false;
}

function walkNodes(nodes: SceneNode[], parentPath: string, visit: (node: SceneNode, path: string) => void): void {
  for (const node of nodes) {
    const path = parentPath ? `${parentPath}/${node.name}` : node.name;
    visit(node, path);
    walkNodes(node.children, path, visit);
  }
}

function isBlockingConsoleLine(line: string): boolean {
  return /\b(error|exception|failed)\b/i.test(line) && !/\bwarning\b/i.test(line);
}

/**
 * Validate a scene tree snapshot.
 * Registration is provided by helpers (cc.js.getClassByName in-scene, or componentListAvailable from main).
 */
export function validateScene(tree: SceneSnapshot, helpers: ValidateSceneHelpers): SceneValidateResult {
  const issues: SceneValidateIssue[] = [];
  let componentsIntact = true;
  let referencesValid = true;
  const reopenable = helpers.reopenable ?? true;

  walkNodes(tree.roots, "", (node, nodePath) => {
    for (const component of node.components) {
      if (!helpers.isComponentRegistered(component.type)) {
        componentsIntact = false;
        issues.push({
          code: "COMPONENT_NOT_REGISTERED",
          severity: "error",
          message: `Component ${component.type} is not registered`,
          nodeKey: node.key,
          nodePath,
        });
      }

      const watched = NULL_REF_FIELDS[component.type] ?? [];
      for (const field of watched) {
        if (!(field in component.properties)) continue;
        if (!isNullishRef(component.properties[field])) continue;
        issues.push({
          code: "EMPTY_REFERENCE",
          severity: "warning",
          message: `${component.type}.${field} is empty`,
          nodeKey: node.key,
          nodePath,
        });
      }
    }
  });

  // Empty refs are warnings; only error-severity reference issues flip the check.
  referencesValid = !issues.some((issue) => issue.code === "EMPTY_REFERENCE" && issue.severity === "error");

  const consoleErrors = (helpers.consoleErrors ?? []).filter(isBlockingConsoleLine);
  const consoleBlockingErrors = consoleErrors.length > 0;
  for (const line of consoleErrors.slice(-20)) {
    issues.push({
      code: "CONSOLE_ERROR",
      severity: "error",
      message: line,
    });
  }

  if (!reopenable) {
    issues.push({
      code: "SCENE_NOT_REOPENABLE",
      severity: "error",
      message: "Scene asset is missing or cannot be reopened",
    });
  }

  const ok = reopenable && componentsIntact && referencesValid && !consoleBlockingErrors
    && !issues.some((issue) => issue.severity === "error");

  return {
    ok,
    sceneUrl: tree.sceneUrl,
    revision: tree.revision,
    issues,
    checks: {
      reopenable,
      componentsIntact,
      referencesValid,
      consoleBlockingErrors,
    },
  };
}

function isClassRegistered(className: string): boolean {
  try {
    const ctor = ccApi().js.getClassByName(className);
    return typeof ctor === "function";
  } catch {
    return false;
  }
}

/** Scene-script methods fragment; spread into `methods` in scene.ts. */
export const validateMethods = {
  sceneValidate() {
    try {
      const tree = snapshotFromDirector();
      const result = validateScene(tree, {
        isComponentRegistered: isClassRegistered,
        reopenable: true,
      });
      return { ok: true as const, result };
    } catch (error) {
      return {
        ok: false as const,
        error: {
          code: "INVALID_REQUEST",
          message: error instanceof Error ? error.message : String(error),
        },
      };
    }
  },
};
