import type { NodeRef } from "../../mcp/src/protocol.js";

/**
 * Resolve a NodeRef against the current scene.
 * Priority: uuid > semanticKey > path > unique name.
 */
export type NodeRefLike = NodeRef;

export type ResolvedNode = {
  uuid: string;
  name: string;
  path?: string;
  semanticKey?: string;
};

export type SceneExecutor = <T>(method: string, argument?: unknown) => Promise<T>;

export function describeNodeRef(ref: NodeRefLike): string {
  if (ref.uuid) return `uuid:${ref.uuid}`;
  if (ref.semanticKey) return `semanticKey:${ref.semanticKey}`;
  if (ref.path) return `path:${ref.path}`;
  if (ref.name) return `name:${ref.name}`;
  return "(empty NodeRef)";
}

export function assertNodeRef(ref: NodeRefLike): void {
  const fields = ["uuid", "semanticKey", "path", "name"] as const;
  if (!ref || typeof ref !== "object" || fields.some((field) =>
    ref[field] !== undefined && (typeof ref[field] !== "string" || !ref[field]!.trim())
  ) || !fields.some((field) => ref[field] !== undefined)) {
    throw Object.assign(
      new Error("NodeRef requires uuid, path, semanticKey, or name"),
      { code: "INVALID_REQUEST" },
    );
  }
}

export function activeNodeRefKind(ref: NodeRefLike): "uuid" | "semanticKey" | "path" | "name" {
  assertNodeRef(ref);
  if (ref.uuid) return "uuid";
  if (ref.semanticKey) return "semanticKey";
  if (ref.path) return "path";
  return "name";
}

/** Resolve a NodeRef via scene-script (`resolveNodeRef` method). */
export async function resolveNodeRef(ref: NodeRefLike, executeScene: SceneExecutor): Promise<ResolvedNode> {
  assertNodeRef(ref);
  return executeScene<ResolvedNode>("resolveNodeRef", ref);
}

/** Convenience wrapper returning only the resolved node uuid. */
export async function resolveNodeUuid(ref: NodeRefLike, executeScene: SceneExecutor): Promise<string> {
  return (await resolveNodeRef(ref, executeScene)).uuid;
}

/** Factory for modules that receive a scene executor once (ui-build, input-sim, etc.). */
export function createNodeResolver(executeScene: SceneExecutor) {
  return {
    resolveNodeRef: (ref: NodeRefLike) => resolveNodeRef(ref, executeScene),
    resolveNodeUuid: (ref: NodeRefLike) => resolveNodeUuid(ref, executeScene),
  };
}
