import { deflateSync } from "node:zlib";
import type { ScreenshotResult } from "../../mcp/src/protocol.js";

type CaptureSuccess = { ok: true; result: ScreenshotResult };
type CaptureFailure = { ok: false; error: { code: string; message: string } };
type CaptureResult = CaptureSuccess | CaptureFailure;

type CameraLike = {
  enabled: boolean;
  priority: number;
  targetTexture: unknown;
  camera?: unknown;
};

type NodeWithCameras = {
  getComponentsInChildren(type: unknown): CameraLike[];
};

type CcCaptureApi = {
  Camera: unknown;
  RenderTexture: new () => {
    reset(options: { width: number; height: number }): void;
    width: number;
    height: number;
    readPixels(x?: number, y?: number, width?: number, height?: number, buffer?: Uint8Array): Uint8Array | null;
    destroy?(): void;
  };
  director: {
    getScene(): NodeWithCameras | null;
    root?: {
      pipeline?: {
        render?(cameras: unknown[]): void;
      };
    };
  };
  view: {
    getVisibleSize(): { width: number; height: number };
  };
};

function fail(code: string, message: string): CaptureFailure {
  return { ok: false, error: { code, message } };
}

function crc32(data: Uint8Array): number {
  let crc = 0xffffffff;
  for (let i = 0; i < data.length; i += 1) {
    crc ^= data[i]!;
    for (let bit = 0; bit < 8; bit += 1) {
      const mask = -(crc & 1);
      crc = (crc >>> 1) ^ (0xedb88320 & mask);
    }
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function pngChunk(type: string, data: Uint8Array): Buffer {
  const typeBuffer = Buffer.from(type, "ascii");
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const crcInput = Buffer.concat([typeBuffer, Buffer.from(data.buffer, data.byteOffset, data.byteLength)]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(crcInput), 0);
  return Buffer.concat([length, typeBuffer, Buffer.from(data.buffer, data.byteOffset, data.byteLength), crc]);
}

/** Encode RGBA8 pixels to a PNG buffer. When flipY is true, rows are flipped (OpenGL bottom-up). */
export function encodePngRgba(rgba: Uint8Array, width: number, height: number, flipY = true): Buffer {
  const stride = width * 4;
  const raw = Buffer.alloc((stride + 1) * height);
  for (let row = 0; row < height; row += 1) {
    const srcRow = flipY ? height - 1 - row : row;
    const dest = row * (stride + 1);
    raw[dest] = 0;
    raw.set(rgba.subarray(srcRow * stride, srcRow * stride + stride), dest + 1);
  }

  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;

  const signature = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
  return Buffer.concat([
    signature,
    pngChunk("IHDR", ihdr),
    pngChunk("IDAT", deflateSync(raw)),
    pngChunk("IEND", new Uint8Array(0)),
  ]);
}

function pickCamera(cameras: CameraLike[]): CameraLike | undefined {
  const enabled = cameras.filter((camera) => camera.enabled !== false);
  const pool = enabled.length ? enabled : cameras;
  return [...pool].sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0))[0];
}

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Scene-script methods fragment. Spread into `scene.ts` `methods`.
 * Best-effort: main Camera → RenderTexture → readPixels → PNG base64.
 */
export const captureMethods = {
  async captureSceneScreenshot(): Promise<CaptureResult> {
    let renderTexture: InstanceType<CcCaptureApi["RenderTexture"]> | undefined;
    let camera: CameraLike | undefined;
    let previousTarget: unknown;

    try {
      const cc = require("cc") as CcCaptureApi;
      const scene = cc.director.getScene();
      if (!scene) return fail("NOT_FOUND", "No scene is currently open");

      const cameras = typeof scene.getComponentsInChildren === "function"
        ? scene.getComponentsInChildren(cc.Camera)
        : [];
      camera = pickCamera(cameras);
      if (!camera) return fail("NOT_FOUND", "No Camera found in the active scene");

      const visible = cc.view.getVisibleSize();
      const width = Math.max(1, Math.floor(visible.width) || 1280);
      const height = Math.max(1, Math.floor(visible.height) || 720);

      renderTexture = new cc.RenderTexture();
      renderTexture.reset({ width, height });
      previousTarget = camera.targetTexture;
      camera.targetTexture = renderTexture;

      const internalCamera = camera.camera;
      if (internalCamera && typeof cc.director.root?.pipeline?.render === "function") {
        cc.director.root.pipeline.render([internalCamera]);
      } else {
        await wait(120);
      }

      const pixels = renderTexture.readPixels(0, 0, width, height)
        ?? renderTexture.readPixels();
      if (!pixels || pixels.length < width * height * 4) {
        return fail("INTERNAL_ERROR", "RenderTexture.readPixels returned empty pixel data");
      }

      const png = encodePngRgba(pixels, width, height, true);
      const result: ScreenshotResult = {
        mimeType: "image/png",
        base64: png.toString("base64"),
        width,
        height,
        source: "scene",
        capturedAt: new Date().toISOString(),
      };
      return { ok: true, result };
    } catch (error) {
      return fail(
        "UNSUPPORTED",
        `Scene screenshot capture failed: ${error instanceof Error ? error.message : String(error)}`,
      );
    } finally {
      if (camera) camera.targetTexture = previousTarget ?? null;
      try {
        renderTexture?.destroy?.();
      } catch {
        // ignore cleanup errors
      }
    }
  },
};
