import type { NodeRefLike, ResolvedNode } from "./node-resolve.js";
import { activeNodeRefKind, assertNodeRef } from "./node-resolve.js";

declare const Editor: {
  App: { path: string };
};
declare const module: { paths: string[] };

const EDITOR_SCENE_NODES = new Set(["Editor Scene Foreground", "Editor Scene Background"]);

type NodeLike = {
  name: string;
  uuid: string;
  parent: NodeLike | null;
  children: NodeLike[];
  components: ComponentLike[];
};

type ComponentLike = {
  constructor: object;
  [key: string]: unknown;
};

function ccApi() {
  return require("cc") as {
    director: { getScene(): NodeLike | null };
    js: { getClassName(instanceOrClass: object): string };
  };
}

function fail(code: string, message: string) {
  return { ok: false as const, error: { code, message } };
}

function currentScene(): NodeLike {
  const scene = ccApi().director.getScene();
  if (!scene) throw new Error("No scene is currently open");
  return scene;
}

function componentType(component: ComponentLike): string {
  return ccApi().js.getClassName(component) || component.constructor.constructor.name;
}

function readSemanticKey(node: NodeLike): string | undefined {
  const identity = node.components.find((component) => componentType(component) === "CreatorAiIdentity");
  const key = identity?.semanticKey;
  return typeof key === "string" && key ? key : undefined;
}

function visibleChildren(node: NodeLike): NodeLike[] {
  return node.children.filter((child) => !EDITOR_SCENE_NODES.has(child.name));
}

function findNodeByUuid(root: NodeLike, uuid: string): NodeLike | undefined {
  if (root.uuid === uuid) return root;
  for (const child of root.children) {
    const found = findNodeByUuid(child, uuid);
    if (found) return found;
  }
  return undefined;
}

function collectByName(root: NodeLike): Map<string, NodeLike[]> {
  const nodes = new Map<string, NodeLike[]>();
  const visit = (node: NodeLike) => {
    if (EDITOR_SCENE_NODES.has(node.name)) {
      for (const child of node.children) visit(child);
      return;
    }
    const matches = nodes.get(node.name) ?? [];
    matches.push(node);
    nodes.set(node.name, matches);
    for (const child of node.children) visit(child);
  };
  for (const child of root.children) visit(child);
  return nodes;
}

function collectBySemanticKey(root: NodeLike): Map<string, NodeLike[]> {
  const nodes = new Map<string, NodeLike[]>();
  const visit = (node: NodeLike) => {
    if (EDITOR_SCENE_NODES.has(node.name)) {
      for (const child of node.children) visit(child);
      return;
    }
    const key = readSemanticKey(node);
    if (key) {
      const matches = nodes.get(key) ?? [];
      matches.push(node);
      nodes.set(key, matches);
    }
    for (const child of node.children) visit(child);
  };
  for (const child of root.children) visit(child);
  return nodes;
}

function buildNodePath(node: NodeLike, scene: NodeLike): string | undefined {
  const segments: string[] = [];
  let current: NodeLike | null = node;
  while (current && current !== scene) {
    if (EDITOR_SCENE_NODES.has(current.name)) return undefined;
    segments.unshift(current.name);
    current = current.parent;
  }
  return segments.length ? segments.join("/") : undefined;
}

function ambiguousReference(label: string, matches: NodeLike[], root: NodeLike): Error {
  const candidates = matches.map((node) => toResolved(node, root));
  return Object.assign(
    new Error(`${label} is ambiguous. Specify a UUID or unique path. Candidates: ${JSON.stringify(candidates)}`),
    { code: "INVALID_REQUEST", candidates },
  );
}

function findNodeByPath(root: NodeLike, path: string): NodeLike {
  const normalized = path.replace(/^\/|\/$/g, "");
  if (normalized.includes("//") || normalized.split("/").some((part) => part === "." || part === "..")) {
    throw Object.assign(new Error(`Node path ${path} is invalid; use a scene-relative hierarchy path`), { code: "INVALID_REQUEST" });
  }
  const segments = normalized.split("/").filter(Boolean);
  if (!segments.length) {
    throw Object.assign(new Error(`Node path ${path} was not found`), { code: "NOT_FOUND" });
  }

  let level = visibleChildren(root);
  let node: NodeLike | undefined;

  for (const segment of segments) {
    const matches = level.filter((candidate) => candidate.name === segment);
    if (!matches.length) {
      throw Object.assign(new Error(`Node path ${path} was not found`), { code: "NOT_FOUND" });
    }
    if (matches.length > 1) {
      throw ambiguousReference(`Node path ${path}`, matches, root);
    }
    node = matches[0]!;
    level = visibleChildren(node);
  }

  return node!;
}

function toResolved(node: NodeLike, scene: NodeLike): ResolvedNode {
  const key = readSemanticKey(node);
  const nodePath = buildNodePath(node, scene);
  return {
    uuid: node.uuid,
    name: node.name,
    ...(key ? { semanticKey: key } : {}),
    ...(nodePath ? { path: nodePath } : {}),
  };
}

/** Scene-graph resolver used by the scene-script process. */
export function resolveNodeRefOnRoot(root: NodeLike, ref: NodeRefLike): ResolvedNode {
  assertNodeRef(ref);
  const kind = activeNodeRefKind(ref);

  if (kind === "uuid") {
    const node = findNodeByUuid(root, ref.uuid!);
    if (!node) {
      throw Object.assign(new Error(`Node uuid ${ref.uuid} was not found`), { code: "NOT_FOUND" });
    }
    return toResolved(node, root);
  }

  if (kind === "semanticKey") {
    const matches = collectBySemanticKey(root).get(ref.semanticKey!) ?? [];
    if (!matches.length) {
      throw Object.assign(new Error(`Node semanticKey ${ref.semanticKey} was not found`), { code: "NOT_FOUND" });
    }
    if (matches.length > 1) {
      throw ambiguousReference(`Node semanticKey ${ref.semanticKey}`, matches, root);
    }
    return toResolved(matches[0]!, root);
  }

  if (kind === "path") {
    return toResolved(findNodeByPath(root, ref.path!), root);
  }

  const matches = collectByName(root).get(ref.name!) ?? [];
  if (!matches.length) {
    throw Object.assign(new Error(`Node name ${ref.name} was not found`), { code: "NOT_FOUND" });
  }
  if (matches.length > 1) {
    throw ambiguousReference(`Node name ${ref.name}`, matches, root);
  }
  return toResolved(matches[0]!, root);
}

/** Preserve legacy string keys while resolving every successful lookup to stable identity. */
export function resolveLegacyNodeKeyOnRoot(root: NodeLike, key: string): ResolvedNode {
  if (typeof key !== "string" || !key.trim()) {
    throw Object.assign(new Error("Node key must be a non-empty string"), { code: "INVALID_REQUEST" });
  }
  const tagged = /^(uuid|semanticKey|path|name):(.*)$/s.exec(key);
  if (tagged) return resolveNodeRefOnRoot(root, { [tagged[1]!]: tagged[2]! });
  const uuidMatch = findNodeByUuid(root, key);
  if (uuidMatch) return toResolved(uuidMatch, root);
  const semanticMatches = collectBySemanticKey(root).get(key) ?? [];
  if (semanticMatches.length > 1) throw ambiguousReference(`Node semanticKey ${key}`, semanticMatches, root);
  if (semanticMatches.length === 1) return toResolved(semanticMatches[0]!, root);
  return resolveNodeRefOnRoot(root, key.includes("/") ? { path: key } : { name: key });
}

export const nodeResolveMethods = {
  resolveNodeRef(ref: NodeRefLike) {
    try {
      return { ok: true as const, result: resolveNodeRefOnRoot(currentScene(), ref) };
    } catch (error) {
      return fail(
        (error as { code?: string }).code ?? "INVALID_REQUEST",
        error instanceof Error ? error.message : String(error),
      );
    }
  },
};
