export type ConsoleLevel = "debug" | "info" | "warning" | "error";

export interface ConsoleEntry {
  time: string;
  level: ConsoleLevel;
  message: string;
}

export interface ConsoleQuery {
  level?: ConsoleLevel;
  since?: string;
  query?: string;
  limit?: number;
}

const SECRET = /((?:bearer\s+)|(?:(?:token|password|secret|authorization)\s*[:=]\s*))(\S+)/gi;

/** Drop credential-shaped fragments and cap length before a log leaves the process. */
export function redactConsoleMessage(message: string): string {
  return message.replace(SECRET, "$1[redacted]").slice(0, 2_000);
}

export function formatConsoleArgs(args: readonly unknown[]): string {
  return redactConsoleMessage(args.map((value) => {
    if (typeof value === "string") return value;
    if (value instanceof Error) return value.message;
    try { return JSON.stringify(value); } catch { return String(value); }
  }).join(" "));
}

export function consoleLevelFromMethod(method: string): ConsoleLevel {
  if (method === "error") return "error";
  if (method === "warn" || method === "warning") return "warning";
  if (method === "debug" || method === "trace") return "debug";
  return "info";
}

/** Fixed-size console ring. `install` wraps a console object once. */
export class ConsoleBuffer {
  private readonly entries: ConsoleEntry[] = [];
  private installed = false;

  constructor(private readonly capacity = 200) {}

  push(level: ConsoleLevel, message: string, time = new Date().toISOString()): void {
    this.entries.push({ time, level, message: redactConsoleMessage(message) });
    if (this.entries.length > this.capacity) this.entries.splice(0, this.entries.length - this.capacity);
  }

  query(filter: ConsoleQuery = {}): ConsoleEntry[] {
    const search = filter.query?.toLowerCase();
    const matched = this.entries.filter((entry) =>
      (!filter.level || entry.level === filter.level) &&
      (!filter.since || entry.time >= filter.since) &&
      (!search || entry.message.toLowerCase().includes(search)),
    );
    const limit = filter.limit ?? this.capacity;
    return matched.slice(-Math.max(0, limit));
  }

  install(target: Record<string, (...args: unknown[]) => unknown>): void {
    if (this.installed) return;
    this.installed = true;
    for (const method of ["log", "info", "warn", "error", "debug"] as const) {
      const original = typeof target[method] === "function" ? target[method] : undefined;
      target[method] = (...args: unknown[]) => {
        this.push(consoleLevelFromMethod(method), formatConsoleArgs(args));
        return original?.(...args);
      };
    }
  }
}
