/** Bit names exposed by `cc.Widget.AlignFlags` in Creator 3.8. */
export interface WidgetAlignFlagBits {
  TOP: number;
  MID: number;
  BOT: number;
  LEFT: number;
  CENTER: number;
  RIGHT: number;
}

export interface WidgetAlignState {
  isAlignTop?: boolean;
  isAlignVerticalCenter?: boolean;
  isAlignBottom?: boolean;
  isAlignLeft?: boolean;
  isAlignHorizontalCenter?: boolean;
  isAlignRight?: boolean;
}

const WIDGET_ALIGN_PROPERTIES = [
  "isAlignTop",
  "isAlignBottom",
  "isAlignLeft",
  "isAlignRight",
  "isAlignHorizontalCenter",
  "isAlignVerticalCenter",
] as const;

export function isWidgetAlignProperty(property: string): boolean {
  return (WIDGET_ALIGN_PROPERTIES as readonly string[]).includes(property);
}

export function widgetAlignBits(flags: Partial<WidgetAlignFlagBits> | undefined): WidgetAlignFlagBits | undefined {
  if (!flags) return undefined;
  const required = ["TOP", "MID", "BOT", "LEFT", "CENTER", "RIGHT"] as const;
  if (required.some((key) => typeof flags[key] !== "number")) return undefined;
  return flags as WidgetAlignFlagBits;
}

/** Rebuild `_alignFlags` from the live booleans using the engine's own bit values. */
export function widgetAlignMask(flags: WidgetAlignFlagBits, widget: WidgetAlignState): number {
  let mask = 0;
  if (widget.isAlignTop) mask |= flags.TOP;
  if (widget.isAlignVerticalCenter) mask |= flags.MID;
  if (widget.isAlignBottom) mask |= flags.BOT;
  if (widget.isAlignLeft) mask |= flags.LEFT;
  if (widget.isAlignHorizontalCenter) mask |= flags.CENTER;
  if (widget.isAlignRight) mask |= flags.RIGHT;
  return mask;
}
