import type { ComponentSchemaProperty } from "../protocol.js";

export const ATTR_DELIM = "$_$";

export interface EnumMember {
  name: string;
  value: number;
}

const ASSET_NAMES = new Set([
  "SpriteFrame", "Font", "Prefab", "Texture2D", "AudioClip", "Material",
  "AnimationClip", "SkeletonData", "ImageAsset", "SpriteAtlas", "JsonAsset",
  "TextAsset", "BufferAsset", "Asset", "TTFFont", "BitmapFont", "LabelAtlas",
]);

/** Read `prop$_$key` from a Cocos class attr bag. */
export function classAttr(attrs: Record<string, unknown> | undefined, property: string, key: string): unknown {
  return attrs?.[`${property}${ATTR_DELIM}${key}`];
}

export function declaredTypeName(typeValue: unknown): string | undefined {
  if (typeof typeValue === "string" && typeValue.trim()) return typeValue.replace(/^cc\./, "");
  if (typeof typeValue === "function" && typeValue.name) return typeValue.name;
  return undefined;
}

export function isAssetTypeName(name: string | undefined): boolean {
  if (!name) return false;
  return name.endsWith("Asset") || name.endsWith("Frame") || ASSET_NAMES.has(name);
}

export function isNodeTypeName(name: string | undefined): boolean {
  return name === "Node";
}

/** Normalize Cocos `enumList` entries into name/value pairs. */
export function enumMembersFromAttr(raw: unknown): EnumMember[] {
  if (!Array.isArray(raw)) return [];
  const members: EnumMember[] = [];
  raw.forEach((item, index) => {
    if (typeof item === "string" && item) {
      members.push({ name: item, value: index });
      return;
    }
    if (!item || typeof item !== "object") return;
    const record = item as { name?: unknown; value?: unknown };
    if (typeof record.name !== "string" || !record.name) return;
    members.push({ name: record.name, value: typeof record.value === "number" ? record.value : index });
  });
  return members;
}

export function classifyDeclaredProperty(input: {
  name: string;
  typeName?: string;
  isComponent: boolean;
  members: EnumMember[];
  runtimeType?: string;
  runtimeArray?: boolean;
}): ComponentSchemaProperty {
  const typeName = input.typeName;
  const nodeReference = isNodeTypeName(typeName) || input.isComponent;
  const asset = !nodeReference && isAssetTypeName(typeName);
  const type = typeName && typeName !== "object" ? typeName : input.runtimeType ?? typeName ?? "object";
  return {
    name: input.name,
    type,
    readonly: false,
    ...(input.runtimeArray ? { array: true } : {}),
    ...(asset && typeName ? { assetType: typeName } : {}),
    ...(nodeReference ? { nodeReference: true } : {}),
    ...(input.members.length ? { enumNames: input.members.map((member) => member.name) } : {}),
  };
}
