import { join } from "node:path";
import type { JsonValue, NodeRef } from "../../mcp/src/protocol.js";
import { resolveNodeRefOnRoot } from "./node-resolve-scene.js";

declare const Editor: {
  App: { path: string };
};
declare const module: { paths: string[] };

type NodeLike = {
  name: string;
  uuid: string;
  parent: NodeLike | null;
  children: NodeLike[];
  components: ComponentLike[];
};

type ComponentLike = {
  enabled?: boolean;
  constructor: object;
  [key: string]: unknown;
};

type AnimationClipLike = { name: string };
type AnimationStateLike = {
  name: string;
  isPlaying: boolean;
  isPaused: boolean;
  isMotionless?: boolean;
  time: number;
  duration: number;
  speed: number;
  wrapMode?: number | string;
};

type AnimationLike = ComponentLike & {
  clips?: AnimationClipLike[];
  defaultClip?: AnimationClipLike | null;
  play(name?: string): void;
  stop(): void;
  getState(name: string): AnimationStateLike | null;
};

type SpineLike = ComponentLike & {
  animation?: string;
  loop?: boolean;
  skeletonData?: {
    uuid?: string;
    _uuid?: string;
    skeletonJson?: unknown;
    getRuntimeData?: () => { animations?: Array<{ name?: string }>; skins?: Array<{ name?: string }> } | null;
    _skeletonCache?: { animations?: Array<{ name?: string }>; skins?: Array<{ name?: string }> };
  } | null;
  setAnimation(trackIndex: number, name: string, loop?: boolean): unknown;
  setSkin(name: string): void;
};

type CcApi = {
  director: { getScene(): NodeLike | null };
  js: {
    getClassName(instanceOrClass: object): string;
    getClassByName(name: string | object): unknown;
  };
  Animation?: unknown;
  sp?: { Skeleton?: unknown };
};

const ANIMATION_TYPES = new Set(["Animation", "cc.Animation"]);
const SPINE_TYPES = new Set(["sp.Skeleton", "Skeleton", "cc.Spine"]);

function ensureCcModulePath(): void {
  try {
    module.paths.push(join(Editor.App.path, "node_modules"));
  } catch {
    // main-process callers never need cc
  }
}

function ccApi(): CcApi {
  ensureCcModulePath();
  return require("cc") as CcApi;
}

function fail(code: string, message: string) {
  return { ok: false as const, error: { code, message } };
}

function currentScene(): NodeLike {
  const scene = ccApi().director.getScene();
  if (!scene) throw Object.assign(new Error("No scene is currently open"), { code: "INVALID_REQUEST" });
  return scene;
}

function componentType(component: ComponentLike): string {
  return ccApi().js.getClassName(component) || component.constructor.constructor.name;
}

function semanticKey(node: NodeLike): string | undefined {
  const identity = node.components.find((component) => componentType(component) === "CreatorAiIdentity");
  return typeof identity?.semanticKey === "string" && identity.semanticKey ? identity.semanticKey : undefined;
}

function resolveNode(ref: NodeRef, root: NodeLike): NodeLike {
  const resolved = resolveNodeRefOnRoot(root, ref);
  const node = findNodeByUuid(root, resolved.uuid);
  if (!node) {
    throw Object.assign(new Error(`Node uuid ${resolved.uuid} was not found`), { code: "NOT_FOUND" });
  }
  return node;
}

function findNodeByUuid(root: NodeLike, uuid: string): NodeLike | undefined {
  if (root.uuid === uuid) return root;
  for (const child of root.children) {
    const found = findNodeByUuid(child, uuid);
    if (found) return found;
  }
  return undefined;
}

function getComponentByTypes(node: NodeLike, types: Set<string>): ComponentLike | undefined {
  return node.components.find((component) => types.has(componentType(component)));
}

function requireAnimation(node: NodeLike): AnimationLike {
  const component = getComponentByTypes(node, ANIMATION_TYPES);
  if (!component) {
    throw Object.assign(new Error(`Node ${node.name} has no cc.Animation component`), { code: "NOT_FOUND" });
  }
  return component as AnimationLike;
}

function spineRegistered(): boolean {
  const cc = ccApi();
  if (cc.sp?.Skeleton) return true;
  const ctor = cc.js.getClassByName("sp.Skeleton");
  return typeof ctor === "function";
}

function requireSpine(node: NodeLike): SpineLike {
  if (!spineRegistered()) {
    throw Object.assign(new Error("Spine module (sp.Skeleton) is not available in this project"), { code: "UNSUPPORTED" });
  }
  const component = getComponentByTypes(node, SPINE_TYPES);
  if (!component) {
    throw Object.assign(new Error(`Node ${node.name} has no sp.Skeleton component`), { code: "NOT_FOUND" });
  }
  return component as SpineLike;
}

function clipNames(animation: AnimationLike): string[] {
  const names = new Set<string>();
  for (const clip of animation.clips ?? []) {
    if (clip?.name) names.add(clip.name);
  }
  if (animation.defaultClip?.name) names.add(animation.defaultClip.name);
  return [...names];
}

function serializeAnimationState(state: AnimationStateLike | null): JsonValue | undefined {
  if (!state) return undefined;
  return {
    name: state.name,
    isPlaying: Boolean(state.isPlaying),
    isPaused: Boolean(state.isPaused),
    isMotionless: Boolean(state.isMotionless),
    time: state.time,
    duration: state.duration,
    speed: state.speed,
    ...(state.wrapMode !== undefined ? { wrapMode: state.wrapMode } : {}),
  };
}

function listSpineNames(data: SpineLike["skeletonData"], field: "animations" | "skins"): string[] {
  if (!data) return [];
  const names = new Set<string>();
  const addFrom = (source: { animations?: Array<{ name?: string }>; skins?: Array<{ name?: string }> } | null | undefined) => {
    if (!source) return;
    const items = source[field] ?? [];
    for (const item of items) {
      if (item?.name) names.add(item.name);
    }
  };
  try {
    addFrom(data.getRuntimeData?.() ?? null);
  } catch {
    // ignore runtime probe failures
  }
  addFrom(data._skeletonCache ?? null);
  const json = data.skeletonJson;
  if (json && typeof json === "object") {
    const record = json as { animations?: Array<{ name?: string }>; skins?: Array<{ name?: string }> };
    addFrom(record);
  }
  return [...names];
}

function skeletonDataUuid(data: SpineLike["skeletonData"]): string | undefined {
  if (!data) return undefined;
  return typeof data.uuid === "string" ? data.uuid : typeof data._uuid === "string" ? data._uuid : undefined;
}

function nodeSummary(node: NodeLike): { [key: string]: JsonValue } {
  const key = semanticKey(node);
  const summary: { [key: string]: JsonValue } = {
    uuid: node.uuid,
    name: node.name,
  };
  if (key) summary.semanticKey = key;
  return summary;
}

export const animationMethods = {
  animationGetState(params: { target: NodeRef }) {
    try {
      const node = resolveNode(params.target, currentScene());
      const animation = requireAnimation(node);
      const clips = clipNames(animation);
      const states = clips.map((name) => serializeAnimationState(animation.getState(name))).filter(Boolean);
      const playing = states.find((state) => {
        const record = state as { isPlaying?: boolean };
        return record.isPlaying;
      }) as { name?: string } | undefined;
      return {
        ok: true as const,
        result: {
          node: nodeSummary(node),
          componentType: componentType(animation),
          defaultClip: animation.defaultClip?.name ?? null,
          clips,
          states,
          playingClip: playing?.name ?? null,
        },
      };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  animationPlay(params: { target: NodeRef; clip?: string }) {
    try {
      const node = resolveNode(params.target, currentScene());
      const animation = requireAnimation(node);
      const clip = params.clip ?? animation.defaultClip?.name;
      if (!clip) {
        throw Object.assign(new Error("No clip specified and cc.Animation has no defaultClip"), { code: "INVALID_REQUEST" });
      }
      const clips = clipNames(animation);
      if (!clips.includes(clip)) {
        throw Object.assign(new Error(`Animation clip ${clip} was not found on ${node.name}`), { code: "NOT_FOUND" });
      }
      animation.play(clip);
      const state = serializeAnimationState(animation.getState(clip));
      return {
        ok: true as const,
        result: {
          node: nodeSummary(node),
          componentType: componentType(animation),
          clip,
          state,
        },
      };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  animationStop(params: { target: NodeRef }) {
    try {
      const node = resolveNode(params.target, currentScene());
      const animation = requireAnimation(node);
      animation.stop();
      return {
        ok: true as const,
        result: {
          node: nodeSummary(node),
          componentType: componentType(animation),
          stopped: true,
        },
      };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  spineGetInfo(params: { target: NodeRef }) {
    try {
      const node = resolveNode(params.target, currentScene());
      const skeleton = requireSpine(node);
      const data = skeleton.skeletonData ?? null;
      return {
        ok: true as const,
        result: {
          node: nodeSummary(node),
          componentType: componentType(skeleton),
          animation: skeleton.animation ?? null,
          loop: Boolean(skeleton.loop),
          skeletonDataUuid: skeletonDataUuid(data) ?? null,
          animations: listSpineNames(data, "animations"),
          skins: listSpineNames(data, "skins"),
        },
      };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  spinePlay(params: { target: NodeRef; animation: string; loop?: boolean }) {
    try {
      const node = resolveNode(params.target, currentScene());
      const skeleton = requireSpine(node);
      skeleton.setAnimation(0, params.animation, params.loop ?? false);
      return {
        ok: true as const,
        result: {
          node: nodeSummary(node),
          componentType: componentType(skeleton),
          animation: params.animation,
          loop: params.loop ?? false,
        },
      };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  spineSetSkin(params: { target: NodeRef; skin: string }) {
    try {
      const node = resolveNode(params.target, currentScene());
      const skeleton = requireSpine(node);
      skeleton.setSkin(params.skin);
      return {
        ok: true as const,
        result: {
          node: nodeSummary(node),
          componentType: componentType(skeleton),
          skin: params.skin,
        },
      };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },
};
