type NodeLike = {
  name: string;
  uuid: string;
  parent: NodeLike | null;
  children: NodeLike[];
  components: ComponentLike[];
  getComponent<T = ComponentLike>(type: unknown): T | null;
  emit(type: string, ...args: unknown[]): void;
};

type ComponentLike = {
  enabled?: boolean;
  clickEvents?: EventHandlerLike[];
  destroy(): boolean;
  constructor: object;
  [key: string]: unknown;
};

type EventHandlerLike = {
  target: NodeLike | null;
  component: string;
  handler: string;
  customEventData?: string;
};

type CcInputApi = {
  input?: {
    emit?(type: unknown, ...args: unknown[]): void;
  };
  systemEvent?: {
    emit?(type: unknown, ...args: unknown[]): void;
  };
  KeyCode?: Record<string, number>;
  Input?: {
    EventType?: {
      KEY_DOWN?: unknown;
      KEY_UP?: unknown;
      MOUSE_DOWN?: unknown;
      MOUSE_UP?: unknown;
      MOUSE_MOVE?: unknown;
    };
  };
  EventKeyboard?: new (keyCode: number, pressed: boolean) => unknown;
  EventMouse?: new (type: unknown) => { setLocation(x: number, y: number): void };
  Button?: {
    EventType?: { CLICK?: string };
    new (): ComponentLike & { clickEvents: EventHandlerLike[] };
  };
  EventHandler?: {
    new (): EventHandlerLike;
    emitEvents(events: EventHandlerLike[], ...args: unknown[]): void;
  };
  director: { getScene(): NodeLike | null };
};

type SceneFail = { ok: false; error: { code: string; message: string } };
type SceneOk<T> = { ok: true; result: T };
type SceneResult<T> = SceneOk<T> | SceneFail;

function ccApi(): CcInputApi {
  return require("cc") as CcInputApi;
}

function fail(code: string, message: string): SceneFail {
  return { ok: false, error: { code, message } };
}

function currentScene(): NodeLike {
  const scene = ccApi().director.getScene();
  if (!scene) throw Object.assign(new Error("No scene is currently open"), { code: "NOT_FOUND" });
  return scene;
}

function findNodeByUuid(root: NodeLike, uuid: string): NodeLike | undefined {
  if (root.uuid === uuid) return root;
  for (const child of root.children) {
    const found = findNodeByUuid(child, uuid);
    if (found) return found;
  }
  return undefined;
}

function requireNode(uuid: string): NodeLike {
  const node = findNodeByUuid(currentScene(), uuid);
  if (!node) throw Object.assign(new Error(`Node ${uuid} was not found`), { code: "NOT_FOUND" });
  return node;
}

function getButton(node: NodeLike): ComponentLike & { clickEvents: EventHandlerLike[] } {
  const cc = ccApi();
  const Button = cc.Button;
  if (!Button) throw Object.assign(new Error("cc.Button is unavailable"), { code: "UNSUPPORTED" });
  const button = node.getComponent(Button);
  if (!button) throw Object.assign(new Error(`Node ${node.uuid} has no Button component`), { code: "NOT_FOUND" });
  if (!Array.isArray(button.clickEvents)) button.clickEvents = [];
  return button as ComponentLike & { clickEvents: EventHandlerLike[] };
}

function simulateButtonOnNode(node: NodeLike): { uuid: string; handlerCount: number; invokedHandlers: number } {
  const cc = ccApi();
  const button = getButton(node);
  const clickType = cc.Button?.EventType?.CLICK ?? "click";
  let invokedHandlers = 0;
  if (cc.EventHandler && typeof cc.EventHandler.emitEvents === "function" && button.clickEvents.length > 0) {
    cc.EventHandler.emitEvents(button.clickEvents, button);
    invokedHandlers = button.clickEvents.length;
  }
  node.emit(clickType, button);
  return { uuid: node.uuid, handlerCount: button.clickEvents.length, invokedHandlers };
}

function bindButtonHandler(node: NodeLike, handlerComponent: string, handlerMethod: string): { uuid: string; handlerCount: number } {
  const cc = ccApi();
  const EventHandler = cc.EventHandler;
  if (!EventHandler) throw Object.assign(new Error("cc.EventHandler is unavailable"), { code: "UNSUPPORTED" });
  const button = getButton(node);
  const handler = new EventHandler();
  handler.target = node;
  handler.component = handlerComponent;
  handler.handler = handlerMethod;
  handler.customEventData = "";
  button.clickEvents.push(handler);
  return { uuid: node.uuid, handlerCount: button.clickEvents.length };
}

function keyCodeFromName(key: string): number | undefined {
  const cc = ccApi();
  const normalized = key.length === 1 ? key.toUpperCase() : key;
  const code = cc.KeyCode?.[normalized] ?? cc.KeyCode?.[key];
  return typeof code === "number" ? code : undefined;
}

function emitInput(type: unknown, event: unknown): boolean {
  const cc = ccApi();
  if (typeof cc.input?.emit === "function") {
    cc.input.emit(type, event);
    return true;
  }
  if (typeof cc.systemEvent?.emit === "function") {
    cc.systemEvent.emit(type, event);
    return true;
  }
  return false;
}

function unsupportedRuntimeInput(message: string): SceneFail {
  return fail(
    "UNSUPPORTED",
    `${message} Editor scene-script cannot inject OS-level input; use input.simulatePreviewInput via Companion while Preview is running.`,
  );
}

/** Scene-script methods fragment; spread into `scene.ts` `methods`. */
export const inputSimSceneMethods = {
  inputSimulateButtonClick(request: { uuid: string }) {
    try {
      return { ok: true as const, result: simulateButtonOnNode(requireNode(request.uuid)) };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  inputBindButtonClickEvent(request: { uuid: string; handlerComponent: string; handlerMethod: string }) {
    try {
      const node = requireNode(request.uuid);
      if (!request.handlerComponent || !request.handlerMethod) {
        throw Object.assign(new Error("handlerComponent and handlerMethod are required"), { code: "INVALID_REQUEST" });
      }
      return { ok: true as const, result: bindButtonHandler(node, request.handlerComponent, request.handlerMethod) };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  inputSimulateKeyPress(request: { key: string; type?: "down" | "up" | "press" }) {
    try {
      const cc = ccApi();
      const keyCode = keyCodeFromName(request.key);
      if (keyCode === undefined) return fail("INVALID_REQUEST", `Unknown key "${request.key}"`);
      const EventKeyboard = cc.EventKeyboard;
      const keyDown = cc.Input?.EventType?.KEY_DOWN;
      const keyUp = cc.Input?.EventType?.KEY_UP;
      if (!EventKeyboard || keyDown === undefined || keyUp === undefined) {
        return unsupportedRuntimeInput("Keyboard simulation is unavailable in this runtime.");
      }
      const phase = request.type ?? "press";
      if (phase === "down" || phase === "press") {
        if (!emitInput(keyDown, new EventKeyboard(keyCode, true))) {
          return unsupportedRuntimeInput("No input event dispatcher is available.");
        }
      }
      if (phase === "up" || phase === "press") {
        if (!emitInput(keyUp, new EventKeyboard(keyCode, false))) {
          return unsupportedRuntimeInput("No input event dispatcher is available.");
        }
      }
      return { ok: true as const, result: { key: request.key, type: phase, keyCode, runtime: "editor-scene" } };
    } catch (error) {
      return unsupportedRuntimeInput(error instanceof Error ? error.message : String(error));
    }
  },

  inputSimulateMouseClick(request: { x: number; y: number }) {
    try {
      const cc = ccApi();
      const EventMouse = cc.EventMouse;
      const mouseDown = cc.Input?.EventType?.MOUSE_DOWN;
      const mouseUp = cc.Input?.EventType?.MOUSE_UP;
      if (!EventMouse || mouseDown === undefined || mouseUp === undefined) {
        return unsupportedRuntimeInput("Mouse click simulation is unavailable in this runtime.");
      }
      const down = new EventMouse(mouseDown);
      down.setLocation(request.x, request.y);
      const up = new EventMouse(mouseUp);
      up.setLocation(request.x, request.y);
      if (!emitInput(mouseDown, down) || !emitInput(mouseUp, up)) {
        return unsupportedRuntimeInput("No input event dispatcher is available.");
      }
      return { ok: true as const, result: { x: request.x, y: request.y, runtime: "editor-scene" } };
    } catch (error) {
      return unsupportedRuntimeInput(error instanceof Error ? error.message : String(error));
    }
  },

  inputSimulateMouseDrag(request: { fromX: number; fromY: number; toX: number; toY: number }) {
    try {
      const cc = ccApi();
      const EventMouse = cc.EventMouse;
      const mouseDown = cc.Input?.EventType?.MOUSE_DOWN;
      const mouseMove = cc.Input?.EventType?.MOUSE_MOVE;
      const mouseUp = cc.Input?.EventType?.MOUSE_UP;
      if (!EventMouse || mouseDown === undefined || mouseMove === undefined || mouseUp === undefined) {
        return unsupportedRuntimeInput("Mouse drag simulation is unavailable in this runtime.");
      }
      const down = new EventMouse(mouseDown);
      down.setLocation(request.fromX, request.fromY);
      const move = new EventMouse(mouseMove);
      move.setLocation(request.toX, request.toY);
      const up = new EventMouse(mouseUp);
      up.setLocation(request.toX, request.toY);
      if (!emitInput(mouseDown, down) || !emitInput(mouseMove, move) || !emitInput(mouseUp, up)) {
        return unsupportedRuntimeInput("No input event dispatcher is available.");
      }
      return {
        ok: true as const,
        result: {
          fromX: request.fromX,
          fromY: request.fromY,
          toX: request.toX,
          toY: request.toY,
          runtime: "editor-scene",
        },
      };
    } catch (error) {
      return unsupportedRuntimeInput(error instanceof Error ? error.message : String(error));
    }
  },
};
