import { normalizeComponentName } from "./component-name.js";
import { resolveLegacyNodeKeyOnRoot } from "./node-resolve-scene.js";

type Point = { x: number; y: number; z?: number };
type ComponentLike = { constructor: object; [key: string]: unknown };
type NodeLike = { name: string; uuid: string; parent: NodeLike | null; children: NodeLike[]; components: ComponentLike[] };
type UiTransform = ComponentLike & {
  contentSize: { width: number; height: number };
  anchorPoint: { x: number; y: number };
  convertToWorldSpaceAR(point: Point): Point;
  convertToNodeSpaceAR(point: Point): Point;
};
type EngineApi = {
  director: { getScene(): NodeLike | null };
  js: { getClassName(instance: object): string };
  view?: { getDesignResolutionSize(): { width: number; height: number } };
  settings?: { querySettings(category: string, name: string): unknown };
};

/** Editor context never implies that a runtime viewport has been measured. */
export function createUiBuildSceneMethods(api: EngineApi) {
  const component = (node: NodeLike, type: string) => node.components.find((item) =>
    normalizeComponentName(api.js.getClassName(item)) === normalizeComponentName(type));
  const root = () => {
    const scene = api.director.getScene();
    if (!scene) throw new Error("No scene is currently open");
    return scene;
  };
  const allNodes = (scene: NodeLike): NodeLike[] => scene.children.flatMap((node) =>
    ["Editor Scene Foreground", "Editor Scene Background"].includes(node.name) ? [] : [node, ...allNodes(node)]);
  const resolve = (scene: NodeLike, key: string) => {
    const uuid = resolveLegacyNodeKeyOnRoot(scene, key).uuid;
    const node = [scene, ...allNodes(scene)].find((candidate) => candidate.uuid === uuid);
    if (!node) throw new Error(`Node ${key} is not part of the editable scene`);
    return node;
  };
  const canvasFor = (scene: NodeLike, target?: string): NodeLike | undefined => {
    if (target) {
      let node: NodeLike | null = resolve(scene, target);
      while (node && node !== scene) {
        if (component(node, "Canvas")) return node;
        node = node.parent;
      }
      return undefined;
    }
    const canvases = allNodes(scene).filter((node) => component(node, "Canvas"));
    if (canvases.length > 1) throw new Error(`Multiple Canvas nodes found; specify a parent. Candidates: ${canvases.map((node) => `${node.name} (${node.uuid})`).join(", ")}`);
    return canvases[0];
  };
  const viewport = (target?: string) => {
    const canvas = canvasFor(root(), target);
    const ui = canvas ? component(canvas, "UITransform") as UiTransform | undefined : undefined;
    const configured = api.settings?.querySettings("screen", "designResolution") as { width?: number; height?: number; policy?: number } | null | undefined;
    const viewSize = api.view?.getDesignResolutionSize();
    const validSize = (size: { width?: number; height?: number } | null | undefined) =>
      Number.isFinite(size?.width) && Number.isFinite(size?.height) && Number(size?.width) > 0 && Number(size?.height) > 0;
    const size = validSize(configured) ? configured : validSize(viewSize) ? viewSize : undefined;
    return {
      source: validSize(configured) ? "project-settings" : size ? "editor-view" : "unknown",
      status: size ? "partial" : "unknown",
      runtimeVisible: "unknown",
      ...(size ? { designWidth: size.width, designHeight: size.height } : {}),
      ...(configured?.policy !== undefined ? { resolutionPolicy: configured.policy } : {}),
      ...(canvas ? { canvasUuid: canvas.uuid } : {}),
      ...(ui && validSize(ui.contentSize) ? { canvasWidth: ui.contentSize.width, canvasHeight: ui.contentSize.height } : {}),
    };
  };
  const wrap = <T>(fn: () => T) => {
    try { return { ok: true as const, result: fn() }; }
    catch (error) { return { ok: false as const, error: { code: "INVALID_REQUEST", message: error instanceof Error ? error.message : String(error) } }; }
  };
  return {
    uiFindCanvas: () => wrap(() => {
      const canvas = canvasFor(root());
      const canvasComponent = canvas ? component(canvas, "Canvas") as ComponentLike | undefined : undefined;
      return canvas ? {
        key: `uuid:${canvas.uuid}`,
        uuid: canvas.uuid,
        name: canvas.name,
        hasCamera: Boolean(canvasComponent?.cameraComponent),
      } : null;
    }),
    uiGetViewportContext: (target?: string) => wrap(() => viewport(target)),
    uiCheckUiBounds: (keys: string[]) => wrap(() => {
      const scene = root();
      const warnings: string[] = [];
      for (const key of keys) {
        const node = resolve(scene, key);
        const canvas = canvasFor(scene, `uuid:${node.uuid}`);
        const ui = component(node, "UITransform") as UiTransform | undefined;
        const canvasUi = canvas ? component(canvas, "UITransform") as UiTransform | undefined : undefined;
        if (!ui || !canvasUi || node === canvas) continue;
        if (typeof ui.convertToWorldSpaceAR !== "function" || typeof canvasUi.convertToNodeSpaceAR !== "function") {
          warnings.push(`Node "${node.name}" (${node.uuid}): Canvas-space bounds unavailable`);
          continue;
        }
        const { width, height } = ui.contentSize;
        const { x: ax, y: ay } = ui.anchorPoint;
        const corners = [[-width * ax, -height * ay], [width * (1 - ax), -height * ay], [-width * ax, height * (1 - ay)], [width * (1 - ax), height * (1 - ay)]]
          .map(([x, y]) => canvasUi.convertToNodeSpaceAR(ui.convertToWorldSpaceAR({ x: x!, y: y!, z: 0 })));
        const left = -canvasUi.contentSize.width * canvasUi.anchorPoint.x;
        const bottom = -canvasUi.contentSize.height * canvasUi.anchorPoint.y;
        const sides = [
          ...(Math.min(...corners.map((point) => point.x)) < left - 0.01 ? ["left"] : []),
          ...(Math.max(...corners.map((point) => point.x)) > left + canvasUi.contentSize.width + 0.01 ? ["right"] : []),
          ...(Math.min(...corners.map((point) => point.y)) < bottom - 0.01 ? ["bottom"] : []),
          ...(Math.max(...corners.map((point) => point.y)) > bottom + canvasUi.contentSize.height + 0.01 ? ["top"] : []),
        ];
        if (sides.length) warnings.push(`Node "${node.name}" (${node.uuid}) extends beyond Canvas ${canvas!.name}: ${sides.join(", ")}`);
      }
      return warnings;
    }),
  };
}

export const uiBuildSceneMethods = {
  uiFindCanvas: () => createUiBuildSceneMethods(require("cc") as EngineApi).uiFindCanvas(),
  uiGetViewportContext: (target?: string) => createUiBuildSceneMethods(require("cc") as EngineApi).uiGetViewportContext(target),
  uiCheckUiBounds: (keys: string[]) => createUiBuildSceneMethods(require("cc") as EngineApi).uiCheckUiBounds(keys),
};
