import { join } from "node:path";
import type {
  ComponentSchema,
  ComponentSchemaProperty,
  JsonValue,
  PatchOperation,
  PrefabCreateRequest,
  SceneNode,
  ScenePatch,
  SceneSnapshot,
} from "../../mcp/src/protocol.js";
import type { PatchResult, UndoResult } from "../../mcp/src/scene-adapter.js";
import { runSceneUserScript } from "./user-script.js";
import { captureMethods } from "./capture.js";
import { inputSimSceneMethods } from "./input-sim-scene.js";
import { resolveLegacyNodeKeyOnRoot, nodeResolveMethods } from "./node-resolve-scene.js";
import { validateMethods } from "./scene-validate.js";
import { animationMethods } from "./scene-animation.js";
import { uiBuildSceneMethods } from "./ui-build-scene.js";
import { componentNameCandidates, normalizeComponentName } from "./component-name.js";
import { UI_DEFAULT_WIDTH, UI_DEFAULT_HEIGHT, UI_DEFAULT_ANCHOR } from "./ui-defaults.js";
import {
  classAttr,
  classifyDeclaredProperty,
  declaredTypeName,
  enumMembersFromAttr,
  isAssetTypeName,
  isNodeTypeName,
  type EnumMember,
} from "../../mcp/src/companion/property-schema.js";
import { ConsoleBuffer, type ConsoleQuery } from "../../mcp/src/companion/console-buffer.js";
import { isWidgetAlignProperty, widgetAlignBits, widgetAlignMask, type WidgetAlignFlagBits } from "../../mcp/src/companion/widget-align.js";

declare const Editor: {
  App: { path: string };
  Message: { request(channel: string, message: string, ...args: unknown[]): Promise<unknown> };
};
declare const module: { paths: string[] };

module.paths.push(join(Editor.App.path, "node_modules"));

type NodeLike = {
  name: string;
  uuid: string;
  active: boolean;
  layer: number;
  parent: NodeLike | null;
  children: NodeLike[];
  components: ComponentLike[];
  addChild(node: NodeLike): void;
  insertChild(node: NodeLike, siblingIndex: number): void;
  addComponent(component: new () => ComponentLike): ComponentLike;
  removeFromParent(): void;
  destroy(): boolean;
};

type ComponentLike = {
  enabled?: boolean;
  string?: string;
  destroy(): boolean;
  constructor: object;
  [key: string]: unknown;
};

type Inverse = () => void;
type WriteGuard =
  | { kind: "node"; uuid: string; name: string; parentUuid?: string }
  | { kind: "component"; uuid: string; component: string }
  | { kind: "property"; uuid: string; component: string; property: string; value: JsonValue | undefined }
  | { kind: "absent"; uuid: string }
  | { kind: "created-shape"; uuid: string; childUuids: string[] };

let lastUndo: { transactionId: string; inverses: Inverse[]; root: NodeLike; revision: string; beforeRevision: string; guards: WriteGuard[] } | undefined;
let recoveryRequired = false;
const sceneConsole = new ConsoleBuffer(200);
const schemaCache = new WeakMap<object, ComponentSchema>();
const enumCache = new WeakMap<object, Map<string, Map<string, number>>>();

function ccApi() {
  return require("cc") as {
    director: { getScene(): NodeLike | null };
    Node: new (name: string) => NodeLike;
    isValid?: (value: unknown, strictMode?: boolean) => boolean;
    assetManager: { loadAny(request: { uuid: string }, callback: (error: Error | null, asset?: unknown) => void): void };
    js: {
      getClassName(instanceOrClass: object): string;
      getClassByName(nameOrClass: string | object): (new () => ComponentLike) | string | undefined;
    };
  };
}

function componentConstructor(name: string): (new () => ComponentLike) | undefined {
  for (const candidate of componentNameCandidates(name)) {
    const constructor = ccApi().js.getClassByName(candidate);
    if (typeof constructor === "function") return constructor;
  }
  return undefined;
}

function fail(code: string, message: string) {
  return { ok: false as const, error: { code, message } };
}

function currentScene(): NodeLike {
  const scene = ccApi().director.getScene();
  if (!scene) throw new Error("No scene is currently open");
  return scene;
}

function componentType(component: ComponentLike): string {
  return ccApi().js.getClassName(component) || component.constructor.constructor.name;
}

function destroyObject(value: { destroy(): boolean }): void {
  value.destroy();
}

function serializeProperty(value: unknown): JsonValue | undefined {
  if (value === null || ["string", "number", "boolean"].includes(typeof value)) return value as JsonValue;
  if (Array.isArray(value)) {
    const serialized = value.map(serializeProperty);
    return serialized.every((item) => item !== undefined) ? serialized as JsonValue[] : undefined;
  }
  if (typeof value !== "object") return undefined;
  const record = value as Record<string, unknown>;
  const uuid = typeof record.uuid === "string" ? record.uuid : typeof record._uuid === "string" ? record._uuid : undefined;
  if (uuid) return { uuid, type: value.constructor?.name ?? "Object" };
  const type = value.constructor?.name;
  const fields = type === "Color" ? ["r", "g", "b", "a"]
    : type === "Size" ? ["width", "height"]
      : type === "Vec2" ? ["x", "y"]
        : type === "Vec3" ? ["x", "y", "z"] : type === "Quat" ? ["x", "y", "z", "w"] : [];
  if (!fields.length) return undefined;
  return Object.fromEntries(fields.map((field) => [field, record[field] as JsonValue]));
}

function copyPropertyForUndo(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(copyPropertyForUndo);
  if (!value || typeof value !== "object") return value;
  const type = value.constructor?.name;
  if (!["Vec2", "Vec3", "Quat", "Size", "Color"].includes(type)) return value;
  const clone = (value as { clone?: () => unknown }).clone;
  if (typeof clone === "function") return clone.call(value);
  const fields = type === "Color" ? ["r", "g", "b", "a"] : type === "Size" ? ["width", "height"]
    : type === "Vec2" ? ["x", "y"] : type === "Quat" ? ["x", "y", "z", "w"] : ["x", "y", "z"];
  const Constructor = value.constructor as new (...args: number[]) => unknown;
  return new Constructor(...fields.map((field) => (value as Record<string, number>)[field]!));
}

function componentProperties(component: ComponentLike): Record<string, JsonValue> {
  const properties: Record<string, JsonValue> = {};
  for (const key of new Set([...Object.keys(component).filter((key) => !key.startsWith("_") && key !== "node"), ...((component.constructor as { __props__?: string[] }).__props__ ?? []).filter((key) => key !== "node" && key !== "_node"), "enabled", "string", "fontSize", "lineHeight", "semanticKey", "action", "spriteFrame", "font", "contentSize", "anchorPoint", "color", "horizontalAlign", "verticalAlign", "layoutType", "resizeMode", "spacingX", "spacingY", "paddingLeft", "paddingRight", "paddingTop", "paddingBottom"])) {
    if (["_objFlags", "_editorExtras"].includes(key)) continue;
    const value = component[key];
    const serialized = serializeProperty(value);
    if (serialized !== undefined) properties[key] = serialized;
  }
  return properties;
}

function semanticKey(node: NodeLike): string | undefined {
  const identity = node.components.find((component) => componentType(component) === "CreatorAiIdentity");
  return typeof identity?.semanticKey === "string" && identity.semanticKey ? identity.semanticKey : undefined;
}

function nodeKey(node: NodeLike): string {
  return semanticKey(node) ?? node.name;
}

function serializeNode(node: NodeLike): SceneNode {
  const identityKey = semanticKey(node);
  return {
    key: nodeKey(node),
    uuid: node.uuid,
    ...Object.fromEntries(["active", "position", "rotation", "scale", "layer"].flatMap((key) => {
      const value = serializeProperty((node as unknown as Record<string, unknown>)[key]);
      return value === undefined ? [] : [[key, value]];
    })),
    ...(identityKey ? { semanticKey: identityKey } : {}),
    name: node.name,
    components: node.components.filter((component) => ccApi().isValid?.(component, true) !== false).map((component) => ({
      type: componentType(component),
      properties: componentProperties(component),
    })),
    children: node.children.filter((child) => !["Editor Scene Foreground", "Editor Scene Background"].includes(child.name)).map(serializeNode),
  };
}

function hash(value: string): string {
  let result = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    result ^= value.charCodeAt(index);
    result = Math.imul(result, 16777619);
  }
  return `rev-${(result >>> 0).toString(16).padStart(8, "0")}`;
}

function snapshot(): SceneSnapshot {
  const scene = currentScene();
  const roots = scene.children
    .filter((node) => node.name !== "Editor Scene Foreground" && node.name !== "Editor Scene Background")
    .map(serializeNode);
  return { sceneUrl: scene.name, revision: hash(JSON.stringify([scene.uuid, roots])), roots };
}

function findNodeByUuid(root: NodeLike, uuid: string): NodeLike | undefined {
  if (root.uuid === uuid) return root;
  for (const child of root.children) {
    const found = findNodeByUuid(child, uuid);
    if (found) return found;
  }
  return undefined;
}

function prefabManager(): {
  createPrefabAssetFromNode(nodeUuid: string, url: string): Promise<string | null | undefined>;
} {
  const modulePath = join(Editor.App.path, "builtin/scene/dist/script/3d/manager/prefab/index.ccc");
  const loaded = require(modulePath) as { default?: unknown };
  const manager = (loaded.default ?? loaded) as {
    createPrefabAssetFromNode?: (nodeUuid: string, url: string) => Promise<string | null | undefined>;
  };
  if (typeof manager.createPrefabAssetFromNode !== "function") {
    throw Object.assign(new Error("Creator 3.8.8 PrefabManager API is unavailable"), { code: "UNSUPPORTED" });
  }
  return manager as { createPrefabAssetFromNode(nodeUuid: string, url: string): Promise<string | null | undefined> };
}

function isComponentConstructor(value: unknown): boolean {
  if (typeof value !== "function") return false;
  const api = ccApi() as { Component?: unknown; js: { isChildClassOf?: (subclass: unknown, superclass: unknown) => boolean } };
  return typeof api.js.isChildClassOf === "function" && api.Component !== undefined && api.js.isChildClassOf(value, api.Component);
}

function rememberEnums(constructor: object, property: string, members: EnumMember[]): void {
  if (!members.length) return;
  let byProperty = enumCache.get(constructor);
  if (!byProperty) {
    byProperty = new Map();
    enumCache.set(constructor, byProperty);
  }
  byProperty.set(property, new Map(members.map((member) => [member.name, member.value])));
}

function schemaForComponent(name: string): ComponentSchema {
  const constructor = componentConstructor(name);
  if (!constructor) {
    throw Object.assign(new Error(`Component ${name} is not registered`), { code: "NOT_FOUND" });
  }
  const cached = schemaCache.get(constructor);
  if (cached) return cached;
  const declaredCtor = constructor as { __props__?: string[]; __attrs__?: Record<string, unknown> };
  const attrs = declaredCtor.__attrs__;
  const declaredNames = (declaredCtor.__props__ ?? []).filter((key) => key !== "node" && key !== "_node" && !key.startsWith("_"));
  const declared = new Map<string, ComponentSchemaProperty>();
  for (const property of declaredNames) {
    const typeValue = classAttr(attrs, property, "type");
    const typeName = declaredTypeName(typeValue);
    const members = enumMembersFromAttr(classAttr(attrs, property, "enumList"));
    rememberEnums(constructor, property, members);
    declared.set(property, classifyDeclaredProperty({
      name: property,
      ...(typeName ? { typeName } : {}),
      isComponent: isComponentConstructor(typeValue),
      members,
    }));
  }
  const node = new (ccApi().Node)("__schema_probe__");
  const component = node.addComponent(constructor);
  const properties: ComponentSchemaProperty[] = [];
  const seen = new Set<string>();
  for (const key of [...declaredNames, ...Object.keys(component), "enabled", "string", "fontSize", "lineHeight", "semanticKey"]) {
    if (seen.has(key) || key.startsWith("_") || key === "node") continue;
    seen.add(key);
    const fromDeclaration = declared.get(key);
    if (fromDeclaration && (fromDeclaration.nodeReference || fromDeclaration.assetType || fromDeclaration.enumNames)) {
      properties.push(fromDeclaration);
      continue;
    }
    const value = component[key];
    const type = Array.isArray(value) ? "array" : value?.constructor?.name ?? typeof value;
    if (["function", "undefined"].includes(typeof value) && !fromDeclaration) continue;
    const runtimeType = type === "object" && fromDeclaration ? fromDeclaration.type : type;
    properties.push({
      ...(fromDeclaration ?? { name: key, type: runtimeType, readonly: false }),
      ...(Array.isArray(value) ? { array: true } : {}),
      ...(!fromDeclaration && (runtimeType.endsWith("Asset") || ["SpriteFrame", "Font", "Prefab"].includes(runtimeType)) ? { assetType: runtimeType } : {}),
    });
  }
  destroyObject(node);
  const schema = { name, properties };
  schemaCache.set(constructor, schema);
  return schema;
}

function propertySchema(component: ComponentLike, property: string): ComponentSchemaProperty | undefined {
  try {
    return schemaForComponent(componentType(component)).properties.find((item) => item.name === property);
  } catch {
    return undefined;
  }
}

function enumValue(component: ComponentLike, property: string, name: string): number | undefined {
  const values = enumCache.get(component.constructor)?.get(property);
  if (!values) return undefined;
  if (!values.has(name)) throw Object.assign(new Error(`Unknown enum name ${name} for ${property}`), { code: "INVALID_REQUEST" });
  return values.get(name);
}

function getComponent(node: NodeLike, type: string): ComponentLike | undefined {
  const normalizedType = normalizeComponentName(type);
  return node.components.find((component) => ccApi().isValid?.(component, true) !== false && normalizeComponentName(componentType(component)) === normalizedType);
}

function convertPropertyValue(current: unknown, value: JsonValue, root: NodeLike, aliases = new Map<string, NodeLike>()): unknown {
  if (Array.isArray(value)) {
    const currentArray = Array.isArray(current) ? current : [];
    return value.map((item, index) => convertPropertyValue(currentArray[index], item, root, aliases));
  }
  if (!value || typeof value !== "object") return value;
  const tagged = value as Record<string, JsonValue>;
  if (tagged.$type === "NodeReference") {
    if (typeof tagged.semanticKey !== "string") throw new Error("NodeReference.semanticKey must be a string");
    return resolveKey(root, tagged.semanticKey, aliases);
  }
  if (tagged.$type === "ComponentReference") {
    if (typeof tagged.node !== "string" || typeof tagged.type !== "string") throw new Error("ComponentReference requires node and type strings");
    const component = getComponent(resolveKey(root, tagged.node, aliases), tagged.type);
    if (!component) throw Object.assign(new Error(`Component ${tagged.type} was not found on ${tagged.node}`), { code: "NOT_FOUND" });
    return component;
  }
  const type = tagged.$type ?? (current as { constructor?: { name?: string } } | null)?.constructor?.name;
  const constructor = (current as { constructor?: new (...args: number[]) => unknown } | null)?.constructor;
  if (typeof constructor !== "function") return value;
  if (type === "Vec2") return new constructor(Number(tagged.x), Number(tagged.y));
  if (type === "Vec3") return new constructor(Number(tagged.x), Number(tagged.y), Number(tagged.z));
  if (type === "Quat") return new constructor(Number(tagged.x), Number(tagged.y), Number(tagged.z), Number(tagged.w));
  if (type === "Size") return new constructor(Number(tagged.width ?? tagged.x), Number(tagged.height ?? tagged.y));
  if (type === "Color") return new constructor(Number(tagged.r), Number(tagged.g), Number(tagged.b), Number(tagged.a));
  return value;
}

const NODE_REF_PREFIX = /^(uuid|path|name|semanticKey):/;

function isAssetShortcut(value: JsonValue): value is { path?: JsonValue; guid?: JsonValue; subAsset?: JsonValue } {
  if (!value || typeof value !== "object" || Array.isArray(value) || typeof value.$type === "string") return false;
  return typeof value.path === "string" || typeof value.guid === "string";
}

async function loadAssetByUuid(uuid: string): Promise<unknown> {
  return new Promise((resolve, reject) => {
    ccApi().assetManager.loadAny({ uuid }, (error, asset) => error ? reject(error) : resolve(asset));
  });
}

function syncWidgetAlign(component: ComponentLike, property: string): void {
  if (normalizeComponentName(componentType(component)) !== "Widget" || !isWidgetAlignProperty(property)) return;
  const api = ccApi() as { Widget?: { AlignFlags?: Partial<WidgetAlignFlagBits> } };
  const flags = widgetAlignBits(api.Widget?.AlignFlags);
  if (!flags) return;
  component._alignFlags = widgetAlignMask(flags, component as {
    isAlignTop?: boolean;
    isAlignVerticalCenter?: boolean;
    isAlignBottom?: boolean;
    isAlignLeft?: boolean;
    isAlignHorizontalCenter?: boolean;
    isAlignRight?: boolean;
  });
}

async function resolveIncomingValue(component: ComponentLike, property: string, value: JsonValue, root: NodeLike, aliases: Map<string, NodeLike>): Promise<unknown> {
  const declared = propertySchema(component, property);
  const current = component[property];
  if (typeof value === "string") {
    const asEnum = enumValue(component, property, value);
    if (asEnum !== undefined) return asEnum;
    if (value.startsWith("db://")) {
      if (!declared?.assetType && !isAssetTypeName(typeof current === "object" && current ? current.constructor?.name : undefined)) {
        return value;
      }
      return loadAsset({ url: value });
    }
    if (declared?.nodeReference || isNodeTypeName((current as { constructor?: { name?: string } } | null)?.constructor?.name)) {
      if (!NODE_REF_PREFIX.test(value)) {
        throw Object.assign(new Error(`Node reference ${property} requires a uuid:, path:, name:, or semanticKey: prefix`), { code: "INVALID_REQUEST" });
      }
      return resolveKey(root, value, aliases);
    }
  }
  if (isAssetShortcut(value)) {
    if (!declared?.assetType && !isAssetTypeName(typeof current === "object" && current ? (current as { constructor?: { name?: string } }).constructor?.name : undefined)) {
      throw Object.assign(new Error(`${property} is not an asset reference`), { code: "INVALID_REQUEST" });
    }
    if (typeof value.guid === "string") return loadAssetByUuid(value.guid);
    if (typeof value.path === "string" && value.path.startsWith("db://")) {
      return loadAsset({ url: value.path, ...(typeof value.subAsset === "string" ? { subAsset: value.subAsset } : {}) });
    }
    throw Object.assign(new Error(`Asset reference for ${property} must be a db:// path or guid`), { code: "INVALID_REQUEST" });
  }
  return convertPropertyValue(current, value, root, aliases);
}

function resolveKey(root: NodeLike, key: string, aliases = new Map<string, NodeLike>()): NodeLike {
  const alias = aliases.get(key);
  if (alias) {
    let ancestor: NodeLike | null = alias;
    while (ancestor && ancestor !== root) ancestor = ancestor.parent;
    if (ancestor === root) return alias;
    throw Object.assign(new Error(`Node ${key} was removed`), { code: "NOT_FOUND" });
  }
  const resolved = resolveLegacyNodeKeyOnRoot(root, key);
  return findNodeByUuid(root, resolved.uuid)!;
}

function propertyGuard(node: NodeLike, component: string, property: string): WriteGuard {
  const owner = normalizeComponentName(component) === "Node" ? node as unknown as ComponentLike : getComponent(node, component);
  if (!owner) throw new Error(`Component ${component} was not found on ${node.name}`);
  return { kind: "property", uuid: node.uuid, component, property, value: serializeProperty(owner[property]) };
}

function guardMatches(root: NodeLike, guard: WriteGuard): boolean {
  const node = findNodeByUuid(root, guard.uuid);
  if (guard.kind === "absent") return !node;
  if (!node) return false;
  if (guard.kind === "node") {
    return node.name === guard.name && node.parent?.uuid === guard.parentUuid;
  }
  if (guard.kind === "created-shape") {
    return JSON.stringify(node.children.map((child) => child.uuid)) === JSON.stringify(guard.childUuids);
  }
  if (guard.kind === "component") return Boolean(getComponent(node, guard.component));
  const owner = normalizeComponentName(guard.component) === "Node" ? node as unknown as ComponentLike : getComponent(node, guard.component);
  return Boolean(owner) && JSON.stringify(serializeProperty(owner![guard.property])) === JSON.stringify(guard.value);
}

function guardsMatch(root: NodeLike, guards: WriteGuard[]): boolean {
  return guards.every((guard) => guardMatches(root, guard));
}

function finalizeGuards(guards: WriteGuard[]): WriteGuard[] {
  const absent = new Set(guards.filter((guard) => guard.kind === "absent").map((guard) => guard.uuid));
  const retained = guards.filter((guard) => {
    if (guard.kind === "absent") return true;
    return !absent.has(guard.uuid);
  });
  const seen = new Set<string>();
  return retained.reverse().filter((guard) => {
    const key = guard.kind === "property" ? `${guard.kind}:${guard.uuid}:${normalizeComponentName(guard.component)}:${guard.property}`
      : guard.kind === "component" ? `${guard.kind}:${guard.uuid}:${normalizeComponentName(guard.component)}`
        : `${guard.kind}:${guard.uuid}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).reverse();
}

function shouldAddUI(parent: NodeLike, mode?: "auto" | "on" | "off"): boolean {
  if (mode === "off") return false;
  if (mode === "on") return true;
  for (let node: NodeLike | null = parent; node; node = node.parent) {
    if (getComponent(node, "Canvas") || getComponent(node, "UITransform")) return true;
  }
  return false;
}

function validate(patch: ScenePatch, root: NodeLike): void {
  // Project only graph identity and component membership; never invoke engine constructors/setters.
  const clone = (node: NodeLike, parent: NodeLike | null): NodeLike => {
    const copy = { name: node.name, uuid: node.uuid, parent, children: [] as NodeLike[],
      components: node.components.map((component) => Object.create(Object.getPrototypeOf(component), Object.getOwnPropertyDescriptors(component))),
    } as NodeLike;
    copy.children = node.children.map((child) => clone(child, copy));
    return copy;
  };
  const projected = clone(root, null);
  const aliases = new Map<string, NodeLike>();
  const checkReferences = (value: JsonValue): void => {
    if (Array.isArray(value)) { value.forEach(checkReferences); return; }
    if (!value || typeof value !== "object") return;
    if (value.$type === "NodeReference" || value.$type === "ComponentReference") {
      convertPropertyValue(undefined, value, projected, aliases);
    } else Object.values(value).forEach(checkReferences);
  };
  let serial = 0;
  for (const operation of patch.operations) {
    if (operation.op === "upsertNode") {
      let node: NodeLike | undefined;
      try { node = resolveKey(projected, operation.key, aliases); } catch (error) {
        if ((error as { code?: string }).code !== "NOT_FOUND" || /^(uuid|path|name|semanticKey):/.test(operation.key)) throw error;
      }
      const parent = operation.parent ? resolveKey(projected, operation.parent, aliases) : projected;
      if (node) {
        if (node === projected) throw new Error("The scene root cannot be updated");
        for (let ancestor: NodeLike | null = parent; ancestor; ancestor = ancestor.parent) {
          if (ancestor === node) throw new Error("A node cannot be parented to itself or its descendant");
        }
        if (operation.parent && node.parent !== parent) {
          node.parent!.children.splice(node.parent!.children.indexOf(node), 1);
          node.parent = parent; parent.children.push(node);
        }
        node.name = operation.name;
      } else {
        node = { name: operation.name, uuid: `__patch_${++serial}`, parent, children: [], components: [] } as unknown as NodeLike;
        parent.children.push(node);
        if (shouldAddUI(parent, operation.uiMode)) {
          const Constructor = componentConstructor("UITransform");
          if (!Constructor) throw new Error("UITransform is not registered");
          node.components.push(Object.create(Constructor.prototype) as ComponentLike);
        }
      }
      aliases.set(operation.key, node);
      continue;
    }
    const node = resolveKey(projected, operation.target, aliases);
    if (operation.op === "removeNode") {
      if (operation.confirmation !== `DELETE_NODE:${operation.target}`) throw new Error(`confirmation must equal DELETE_NODE:${operation.target}`);
      if (!node.parent) throw new Error("The scene root cannot be removed");
      node.parent.children.splice(node.parent.children.indexOf(node), 1); node.parent = null;
      continue;
    }
    if (operation.op === "upsertComponent") {
      const constructor = componentConstructor(operation.type);
      if (!constructor) throw Object.assign(new Error(`Component ${operation.type} is not registered`), { code: "NOT_FOUND" });
      let component = getComponent(node, operation.type);
      if (!component) { component = Object.create(constructor.prototype) as ComponentLike; node.components.push(component); }
      // Only identity influences later resolution; no arbitrary setters run during preflight.
      if (normalizeComponentName(operation.type) === "CreatorAiIdentity" && operation.properties?.semanticKey !== undefined) {
        Object.defineProperty(component, "semanticKey", { value: operation.properties.semanticKey, configurable: true, writable: true });
      }
      Object.values(operation.properties ?? {}).forEach(checkReferences);
    } else if (normalizeComponentName(operation.component) === "Node") {
      if (!["active", "position", "rotation", "scale", "eulerAngles", "layer"].includes(operation.property)) throw new Error(`Node property ${operation.property} is not writable`);
    } else if (!getComponent(node, operation.component)) {
      throw Object.assign(new Error(`Component ${operation.component} was not found on ${operation.target}`), { code: "NOT_FOUND" });
    }
    if (operation.op === "setProperty") checkReferences(operation.value);
  }
}

async function loadAsset(reference: { url: string; subAsset?: string | undefined }): Promise<unknown> {
  const info = await Editor.Message.request("asset-db", "query-asset-info", reference.url) as {
    uuid?: string;
    subAssets?: Record<string, { name?: string; uuid?: string; url?: string }> | Array<{ name?: string; uuid?: string; url?: string }>;
  } | null;
  if (!info) throw Object.assign(new Error(`Asset ${reference.url} was not found`), { code: "NOT_FOUND" });
  let uuid = info.uuid;
  if (reference.subAsset) {
    const subAssets = info.subAssets;
    if (Array.isArray(subAssets)) {
      uuid = subAssets.find((item) => item.name === reference.subAsset || item.url?.endsWith(reference.subAsset!))?.uuid;
    } else if (subAssets) {
      uuid = Object.values(subAssets).find(
        (item) => item.name === reference.subAsset || item.url?.endsWith(`/${reference.subAsset}`),
      )?.uuid;
    }
  }
  if (!uuid) throw Object.assign(new Error(`Asset reference ${reference.url} could not be resolved`), { code: "NOT_FOUND" });
  return new Promise((resolve, reject) => {
    ccApi().assetManager.loadAny({ uuid: uuid! }, (error, asset) => error ? reject(error) : resolve(asset));
  });
}

async function applyOperation(operation: PatchOperation, root: NodeLike, inverses: Inverse[], aliases: Map<string, NodeLike>, autoAdded: Array<{ nodeUuid: string; type: string }>, guards: WriteGuard[], created: Set<string>): Promise<void> {
  if (operation.op === "upsertNode") {
    let existing: NodeLike | undefined;
    try { existing = resolveKey(root, operation.key, aliases); } catch (error) {
      if ((error as { code?: string }).code !== "NOT_FOUND" || /^(uuid|path|name|semanticKey):/.test(operation.key)) throw error;
    }
    const parent = operation.parent ? resolveKey(root, operation.parent, aliases) : root;
    if (existing) {
      if (existing === root) throw new Error("The scene root cannot be updated");
      let ancestor: NodeLike | null = parent;
      while (ancestor) {
        if (ancestor === existing) throw new Error("A node cannot be parented to itself or its descendant");
        ancestor = ancestor.parent;
      }
      const oldName = existing.name;
      const oldParent = existing.parent!;
      const oldIndex = oldParent.children.indexOf(existing);
      inverses.push(() => { existing!.name = oldName; oldParent.insertChild(existing!, oldIndex); });
      existing.name = operation.name;
      if (operation.parent && parent !== existing.parent) parent.addChild(existing);
      aliases.set(operation.key, existing);
      guards.push({ kind: "node", uuid: existing.uuid, name: existing.name, ...(existing.parent ? { parentUuid: existing.parent.uuid } : {}) });
      guards.push(propertyGuard(existing, "Node", "active"));
      return;
    }
    const node = new (ccApi().Node)(operation.name);
    inverses.push(() => { node.removeFromParent(); destroyObject(node); });
    parent.addChild(node);
    created.add(node.uuid);
    aliases.set(operation.key, node);
    if (shouldAddUI(parent, operation.uiMode) && !getComponent(node, "UITransform")) {
      const Constructor = componentConstructor("UITransform");
      if (!Constructor) throw new Error("UITransform is not registered");
      const transform = node.addComponent(Constructor);
      transform.contentSize = convertPropertyValue(transform.contentSize, { $type: "Size", width: UI_DEFAULT_WIDTH, height: UI_DEFAULT_HEIGHT }, root, aliases);
      transform.anchorPoint = convertPropertyValue(transform.anchorPoint, { $type: "Vec2", x: UI_DEFAULT_ANCHOR, y: UI_DEFAULT_ANCHOR }, root, aliases);
      autoAdded.push({ nodeUuid: node.uuid, type: "cc.UITransform" });
    }
    guards.push({ kind: "node", uuid: node.uuid, name: node.name, ...(node.parent ? { parentUuid: node.parent.uuid } : {}) });
    guards.push(propertyGuard(node, "Node", "active"));
    return;
  }

  const node = resolveKey(root, operation.target, aliases);
  if (operation.op === "removeNode") {
    const parent = node.parent;
    if (!parent) throw Object.assign(new Error("The scene root cannot be removed"), { code: "INVALID_REQUEST" });
    const siblingIndex = parent.children.indexOf(node);
    inverses.push(() => parent.insertChild(node, siblingIndex));
    node.removeFromParent();
    guards.push({ kind: "absent", uuid: node.uuid });
    return;
  }
  if (operation.op === "upsertComponent") {
    let component = getComponent(node, operation.type);
    if (!component) {
      const constructor = componentConstructor(operation.type);
      if (typeof constructor !== "function") throw new Error(`Invalid component ${operation.type}`);
      const existingComponents = new Set(node.components);
      inverses.push(() => {
        for (const item of [...node.components].reverse()) {
          if (!existingComponents.has(item)) destroyObject(item);
        }
      });
      component = node.addComponent(constructor);
    }
    guards.push({ kind: "component", uuid: node.uuid, component: operation.type });
    for (const [property, value] of Object.entries(operation.properties ?? {})) {
      const oldValue = copyPropertyForUndo(component[property]);
      inverses.push(() => (component![property] = oldValue));
      component[property] = await resolveIncomingValue(component, property, value, root, aliases);
      syncWidgetAlign(component, property);
      guards.push(propertyGuard(node, operation.type, property));
    }
    return;
  }

  if (normalizeComponentName(operation.component) === "Node" &&
      !["active", "position", "rotation", "scale", "eulerAngles", "layer"].includes(operation.property)) {
    throw Object.assign(new Error(`Node property ${operation.property} is not writable`), { code: "INVALID_REQUEST" });
  }
  const component = normalizeComponentName(operation.component) === "Node"
    ? node as unknown as ComponentLike : getComponent(node, operation.component);
  if (!component) throw Object.assign(new Error(`Component ${operation.component} was not found on ${operation.target}`), { code: "NOT_FOUND" });
  const oldValue = copyPropertyForUndo(component[operation.property]);
  inverses.push(() => (component[operation.property] = oldValue));
  component[operation.property] = operation.op === "bindAsset"
    ? await loadAsset(operation.asset)
    : await resolveIncomingValue(component, operation.property, operation.value, root, aliases);
  syncWidgetAlign(component, operation.property);
  guards.push(propertyGuard(node, operation.component, operation.property));
}

function rollback(inverses: Inverse[]): void {
  const errors: string[] = [];
  for (const inverse of [...inverses].reverse()) {
    try { inverse(); } catch (error) { errors.push(error instanceof Error ? error.message : String(error)); }
  }
  if (errors.length) throw new Error(errors.join("; "));
}

function settleScene(): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, 16));
}

export function load(): void {
  sceneConsole.install(console as unknown as Record<string, (...args: unknown[]) => unknown>);
}
export function unload(): void {
  lastUndo = undefined;
  recoveryRequired = false;
}

export const methods = {
  ...captureMethods,
  ...inputSimSceneMethods,
  ...nodeResolveMethods,
  ...uiBuildSceneMethods,
  ...validateMethods,
  ...animationMethods,

  getTree(options?: { acknowledgeRecovery?: boolean }) {
    try {
      const result = snapshot();
      if (options?.acknowledgeRecovery !== false) recoveryRequired = false;
      return { ok: true as const, result };
    } catch (error) {
      return fail("INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  requireRecoveryRead() {
    recoveryRequired = true;
    return { ok: true as const, result: null };
  },

  async acceptLastWriteAfterSave() {
    if (!lastUndo || currentScene() !== lastUndo.root) {
      return fail("REVISION_CONFLICT", "The document changed before the saved transaction could be finalized");
    }
    await settleScene();
    if (!lastUndo || currentScene() !== lastUndo.root) {
      return fail("REVISION_CONFLICT", "The document changed before the saved transaction could be finalized");
    }
    if (!guardsMatch(lastUndo.root, lastUndo.guards)) {
      const mismatches = lastUndo.guards.filter((guard) => !guardMatches(lastUndo!.root, guard)).map((guard) =>
        guard.kind === "property" ? `${guard.kind}:${guard.uuid}:${guard.component}.${guard.property}` : `${guard.kind}:${guard.uuid}`,
      );
      lastUndo = undefined;
      return fail("REVISION_CONFLICT", `The document changed while the transaction was being saved; undo was refused (${mismatches.join(", ")})`);
    }
    const saved = snapshot();
    lastUndo.revision = saved.revision;
    return { ok: true as const, result: saved };
  },

  assertLastWriteCurrent() {
    if (!lastUndo || currentScene() !== lastUndo.root) {
      return fail("REVISION_CONFLICT", "The open document changed before the transaction could be saved");
    }
    return { ok: true as const, result: null };
  },

  async applyPatch(patch: ScenePatch) {
    if (recoveryRequired) return fail("RECOVERY_REQUIRED", "Previous rollback failed; read the scene again before writing");
    const before = snapshot();
    if (patch.expectedRevision !== before.revision) {
      return fail("REVISION_CONFLICT", `Expected ${patch.expectedRevision}, current revision is ${before.revision}`);
    }
    const root = currentScene();
    const inverses: Inverse[] = [];
    try {
      validate(patch, root);
      const aliases = new Map<string, NodeLike>();
      const autoAddedComponents: Array<{ nodeUuid: string; type: string }> = [];
      const guards: WriteGuard[] = [];
      const created = new Set<string>();
      for (const operation of patch.operations) {
        if (currentScene() !== root) throw Object.assign(new Error("The open document changed during the transaction"), { code: "REVISION_CONFLICT" });
        await applyOperation(operation, root, inverses, aliases, autoAddedComponents, guards, created);
        if (currentScene() !== root) throw Object.assign(new Error("The open document changed during the transaction"), { code: "REVISION_CONFLICT" });
      }
      for (const uuid of created) {
        const node = findNodeByUuid(root, uuid);
        if (node) guards.push({
          kind: "created-shape",
          uuid,
          childUuids: node.children.map((child) => child.uuid),
        });
      }
      const finalizedGuards = finalizeGuards(guards);
      await settleScene();
      if (currentScene() !== root || !guardsMatch(root, finalizedGuards)) {
        const mismatches = finalizedGuards.filter((guard) => !guardMatches(root, guard)).map((guard) =>
          guard.kind === "property" ? `${guard.kind}:${guard.uuid}:${guard.component}.${guard.property}` : `${guard.kind}:${guard.uuid}`,
        );
        throw Object.assign(new Error(`The document changed while the transaction was settling; rollback was refused (${mismatches.join(", ")})`), {
          code: "REVISION_CONFLICT",
          skipRollback: true,
        });
      }
      const after = snapshot();
      const transactionId = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
      lastUndo = { transactionId, inverses, root, revision: after.revision, beforeRevision: before.revision, guards: finalizedGuards };
      const nodeUuids = Object.fromEntries([...aliases].filter(([, node]) => findNodeByUuid(root, node.uuid)).map(([key, node]) => [key, node.uuid]));
      const result: PatchResult = { transactionId, beforeRevision: before.revision, after, nodeUuids, autoAddedComponents };
      return { ok: true as const, result };
    } catch (error) {
      const original = error instanceof Error ? error.message : String(error);
      if ((error as { skipRollback?: boolean }).skipRollback) {
        lastUndo = undefined;
        recoveryRequired = true;
        return fail("REVISION_CONFLICT", original);
      }
      try {
        rollback(inverses);
        if (snapshot().revision !== before.revision) throw new Error("Restored scene differs from the pre-write scene");
      } catch (rollbackError) {
        lastUndo = undefined;
        recoveryRequired = true;
        return fail("ROLLBACK_FAILED", `${original}; rollback failed: ${String(rollbackError)}`);
      }
      const code = (error as { code?: string }).code ?? "INVALID_REQUEST";
      return fail(code, error instanceof Error ? error.message : String(error));
    }
  },

  undoLastWrite() {
    if (!lastUndo) return fail("NO_UNDO", "There is no MCP write to undo");
    const { transactionId, inverses, root, revision, beforeRevision } = lastUndo;
    if (currentScene() !== root || snapshot().revision !== revision) {
      lastUndo = undefined;
      return fail("REVISION_CONFLICT", "The document changed after the last MCP write; undo was refused");
    }
    lastUndo = undefined;
    try {
      rollback(inverses);
      if (snapshot().revision !== beforeRevision) throw new Error("Restored scene differs from the pre-write scene");
    } catch (error) {
      recoveryRequired = true;
      return fail("ROLLBACK_FAILED", String(error));
    }
    const result: UndoResult = { transactionId, restored: snapshot() };
    return { ok: true as const, result };
  },

  getConsoleLogs(filter?: ConsoleQuery) {
    sceneConsole.install(console as unknown as Record<string, (...args: unknown[]) => unknown>);
    return { ok: true as const, result: sceneConsole.query(filter ?? {}) };
  },

  getComponentSchema(name: string) {
    try {
      return { ok: true as const, result: schemaForComponent(name) };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  getNodeUuid(key: string) {
    try {
      return { ok: true as const, result: resolveKey(currentScene(), key).uuid };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  setSemanticKeyByUuid(request: { uuid: string; semanticKey: string }) {
    try {
      const node = findNodeByUuid(currentScene(), request.uuid);
      if (!node) throw Object.assign(new Error(`Node ${request.uuid} was not found`), { code: "NOT_FOUND" });
      let identity = getComponent(node, "CreatorAiIdentity");
      if (!identity) {
        const constructor = ccApi().js.getClassByName("CreatorAiIdentity");
        if (typeof constructor !== "function") {
          throw Object.assign(new Error("CreatorAiIdentity is not registered"), { code: "NOT_FOUND" });
        }
        identity = node.addComponent(constructor);
      }
      identity.semanticKey = request.semanticKey;
      return { ok: true as const, result: serializeNode(node) };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },

  prefabProbe() {
    try {
      const manager = prefabManager();
      return {
        ok: true as const,
        result: {
          supported: typeof manager.createPrefabAssetFromNode === "function",
          creatorVersion: "3.8.8",
          strategy: "PrefabManager.createPrefabAssetFromNode",
        },
      };
    } catch (error) {
      return fail("UNSUPPORTED", error instanceof Error ? error.message : String(error));
    }
  },

  async prefabCreate(request: PrefabCreateRequest) {
    try {
      const node = resolveKey(currentScene(), request.sourceNodeKey);
      const uuid = await prefabManager().createPrefabAssetFromNode(node.uuid, request.url);
      if (!uuid) throw new Error("Creator did not return a Prefab UUID");
      return { ok: true as const, result: { uuid, url: request.url } };
    } catch (error) {
      return fail((error as { code?: string }).code ?? "INTERNAL_ERROR", error instanceof Error ? error.message : String(error));
    }
  },

  /**
   * Scene-side user script entry (confirm EXECUTE_SCENE_SCRIPT enforced by bridge-service).
   * Invoked via execute-scene-script method "runUserScript".
   */
  async runUserScript(request: { code: string; timeoutMs?: number }) {
    try {
      const result = await runSceneUserScript(request.code, request.timeoutMs);
      return { ok: true as const, result };
    } catch (error) {
      return fail("INVALID_REQUEST", error instanceof Error ? error.message : String(error));
    }
  },
};
